import type { ClaimCategory, ClaimRecord } from "./types";

/**
 * Second batch of source-backed statements: medicines whose US label has no patient-directed Medication Guide.
 * Each statement rests on one short exact passage of the stored US prescribing information (the sections that
 * speak to the prescriber, or tell the prescriber what to counsel patients about). The wording restates that
 * passage in plain language for a patient. It adds no dose, number, warning or condition the passage lacks, and
 * explains a medical term only briefly where a lay reader would otherwise be stuck.
 *
 * US labels only. None is an Indian label. None has been reviewed.
 */
export type Make = (slug: string, category: ClaimCategory, loinc: string, passage: string, wording: string, limitations?: string[], replacesRule?: string) => ClaimRecord;

const IND = "34067-9";
const DOSE = "34068-7";
const CONTRA = "34070-3";
const WARN = "34071-1";
const ADVERSE = "34084-4";
const PC = "34076-0";
const BOX = "34066-1";
const INTER = "34073-7";

const LIST_PI = ["US prescribing information, which is written for clinicians: this restates it in plain words.", "The label lists events reported in people taking the medicine and gives no frequencies.", "US label only: Indian approval, strengths and warnings may differ."];

export function batch2(c: Make): ClaimRecord[] {
  return [
    /* ---- risperidone tablets ---- */
    c("risperidone", "used-for", IND, "Risperidone tablets are an atypical antipsychotic indicated for: Treatment of schizophrenia (1.1) As monotherapy or adjunctive therapy with lithium or valproate, for the treatment of acute manic or mixed episodes associated with Bipolar I Disorder (1.2) Treatment of irritability associated with autistic disorder (1.3)", "Risperidone is an atypical antipsychotic. The US label lists these uses: schizophrenia; acute manic or mixed episodes of bipolar I disorder (on its own, or together with lithium or valproate); and irritability associated with autistic disorder."),
    c("risperidone", "precaution", BOX, "Elderly patients with dementia-related psychosis treated with antipsychotic drugs are at an increased risk of death. Risperidone is not approved for the treatment of patients with dementia-related psychosis.", "Elderly people with dementia-related psychosis who are treated with antipsychotic medicines are at an increased risk of death. Risperidone is not approved for treating dementia-related psychosis."),
    c("risperidone", "contraindication", CONTRA, "Risperidone tablets are contraindicated in patients with a known hypersensitivity to either risperidone or paliperidone, or to any of the excipients in the risperidone tablets formulation.", "Do not take it if you are known to be allergic (hypersensitive) to risperidone, to paliperidone, or to any other ingredient in the tablets."),
    c("risperidone", "urgent-help", PC, "Counsel patients about a potentially fatal adverse reaction, Neuroleptic Malignant Syndrome (NMS), that has been reported in association with administration of antipsychotic drugs. Advise patients, family members, or caregivers to contact the healthcare provider or report to the emergency room if they experience signs and symptoms of NMS, including hyperpyrexia, muscle rigidity, altered mental status including delirium, and evidence of autonomic instability (irregular pulse or blood pressure, tachycardia, diaphoresis, and cardiac dysrhythmia)", "Antipsychotic medicines have been linked to a potentially fatal reaction called neuroleptic malignant syndrome (NMS). Contact your healthcare provider or go to the emergency room if you or a family member have a very high fever, muscle stiffness, confusion or delirium, an irregular pulse or blood pressure, a fast heartbeat, sweating or an irregular heart rhythm."),
    c("risperidone", "side-effects", PC, "Counsel patients on the signs and symptoms of tardive dyskinesia and to contact their healthcare provider if these abnormal movements occur", "Tardive dyskinesia is a problem of abnormal movements that can be linked to antipsychotic medicines. Contact your healthcare provider if you notice abnormal movements."),
    c("risperidone", "side-effects", PC, "Educate patients about the risk of metabolic changes, how to recognize symptoms of hyperglycemia and diabetes mellitus, and the need for specific monitoring, including blood glucose, lipids, and weight", "Risperidone can cause metabolic changes. Your healthcare provider should explain how to recognise the symptoms of high blood sugar (hyperglycemia) and diabetes, and why your blood sugar, blood fats (lipids) and weight need to be monitored."),
    c("risperidone", "precaution", PC, "Educate patients about the risk of orthostatic hypotension and syncope, particularly at the time of initiating treatment, re-initiating treatment, or increasing the dose", "It can cause low blood pressure when you stand up (orthostatic hypotension) and fainting (syncope), particularly when treatment is started or restarted, or when the dose is increased."),
    c("risperidone", "monitoring", PC, "Advise patients with a pre-existing low WBC or a history of drug induced leukopenia/neutropenia they should have their CBC monitored while taking risperidone", "If you already have a low white blood cell count, or have had a drop in white cells caused by a medicine (leukopenia or neutropenia), you should have your blood count (CBC) monitored while taking risperidone."),
    c("risperidone", "side-effects", PC, "Counsel patients on signs and symptoms of hyperprolactinemia that may be associated with chronic use of risperidone. Advise them to seek medical attention if they experience any of the following: amenorrhea or galactorrhea in females, erectile dysfunction or gynecomastia in males", "Long-term use may raise the hormone prolactin (hyperprolactinemia). Seek medical attention if a woman has missed periods (amenorrhea) or breast milk production (galactorrhea), or if a man has erectile dysfunction or breast enlargement (gynecomastia)."),
    c("risperidone", "precaution", PC, "Caution patients about performing activities requiring mental alertness, such as operating hazardous machinery, or operating a motor vehicle until they are reasonably certain that risperidone therapy does not affect them adversely", "Do not do activities that need you to be mentally alert, such as operating hazardous machinery or driving, until you are reasonably certain that risperidone does not affect you badly."),
    c("risperidone", "urgent-help", PC, "Advise patients of the possibility of painful or prolonged penile erections (priapism). Instruct the patient to seek immediate medical attention in the event of priapism", "A painful or prolonged erection (priapism) is possible. Seek immediate medical attention if it happens."),
    c("risperidone", "precaution", PC, "Counsel patients regarding appropriate care in avoiding overheating and dehydration", "Take care to avoid overheating and dehydration."),
    c("risperidone", "interactions", PC, "Advise patients to inform their healthcare providers if they are taking, or plan to take any prescription or over-the-counter drugs, as there is a potential for interactions", "Tell your healthcare provider about any prescription or over-the-counter medicine you are taking or plan to take, because interactions are possible."),
    c("risperidone", "interactions", INTER, "Carbamazepine and other enzyme inducers decrease plasma concentrations of risperidone. Increase the risperidone dose up to double the patient’s usual dose. Titrate slowly.", "Carbamazepine and similar medicines lower the level of risperidone in the blood. The label says the risperidone dose is then increased, by up to double the usual dose, slowly. Your prescriber decides this, not you."),
    c("risperidone", "interactions", INTER, "Fluoxetine, paroxetine, and other CYP2D6 enzyme inhibitors increase plasma concentrations of risperidone. Reduce the initial dose. Do not exceed a final dose of 8 mg per day of risperidone.", "Fluoxetine, paroxetine and similar medicines raise the level of risperidone in the blood. The label says the starting dose should be reduced and the final dose should not exceed 8 mg a day. Your prescriber decides this, not you."),
    c("risperidone", "precaution", PC, "Advise patients to avoid alcohol while taking risperidone", "Avoid alcohol while taking risperidone."),
    c("risperidone", "precaution", PC, "Advise patients to notify their healthcare provider if they become pregnant or intend to become pregnant during treatment with risperidone. Advise patients that risperidone may cause extrapyramidal and/or withdrawal symptoms in a neonate.", "Tell your healthcare provider if you become pregnant or intend to become pregnant during treatment. Risperidone may cause extrapyramidal symptoms (movement problems) and/or withdrawal symptoms in a newborn baby."),
    c("risperidone", "precaution", PC, "Advise breastfeeding women using risperidone to monitor infants for somnolence, failure to thrive, jitteriness, and extrapyramidal symptoms (tremors and abnormal muscle movements) and to seek medical care if they notice these signs", "If you are breastfeeding while using risperidone, watch your baby for unusual sleepiness, poor growth or feeding (failure to thrive), jitteriness, and tremors or abnormal muscle movements, and seek medical care if you notice these signs."),
    c("risperidone", "side-effects", ADVERSE, "The most common adverse reactions in clinical trials (> 5% and twice placebo) were parkinsonism, akathisia, dystonia, tremor, sedation, dizziness, anxiety, blurred vision, nausea, vomiting, upper abdominal pain, stomach discomfort, dyspepsia, diarrhea, salivary hypersecretion, constipation, dry mouth, increased appetite, increased weight, fatigue, rash, nasal congestion, upper respiratory tract infection, nasopharyngitis, and pharyngolaryngeal pain.", "The most common side effects in trials (more than 5% of people and twice as often as with a dummy tablet) were: parkinsonism (movement problems like those of Parkinson's disease), akathisia (inner restlessness), dystonia (muscle spasms), tremor, sedation, dizziness, anxiety, blurred vision, nausea, vomiting, pain in the upper abdomen, stomach discomfort, indigestion, diarrhoea, extra saliva, constipation, dry mouth, increased appetite, weight gain, tiredness, rash, nasal congestion, upper respiratory tract infection, a cold-like nose and throat infection (nasopharyngitis) and throat pain.", ["US prescribing information, which is written for clinicians: this restates it in plain words.", "Figures come from US trials and cannot predict how common a side effect is for any one person.", "US label only: Indian approval, strengths and warnings may differ."]),

    /* ---- haloperidol tablets ---- */
    c("haloperidol", "used-for", IND, "Haloperidol tablets, USP are indicated for use in the management of manifestations of psychotic disorders.", "Haloperidol is used in the management of the symptoms of psychotic disorders."),
    c("haloperidol", "used-for", IND, "Haloperidol tablets are indicated for the control of tics and vocal utterances of Tourette’s Disorder in children and adults.", "It is also used to control the tics and vocal utterances (sounds or words that cannot be held back) of Tourette's disorder in children and adults."),
    c("haloperidol", "precaution", BOX, "Elderly patients with dementia-related psychosis treated with antipsychotic drugs are at an increased risk of death.", "Elderly people with dementia-related psychosis who are treated with antipsychotic medicines are at an increased risk of death. The label says haloperidol is not approved for treating dementia-related psychosis."),
    c("haloperidol", "contraindication", CONTRA, "Haloperidol tablets are contraindicated in severe toxic central nervous system depression or comatose states from any cause and in individuals who are hypersensitive to this drug or have Parkinson’s disease.", "Do not take it if you are in a coma or have severe toxic depression of the central nervous system (a dangerous slowing of brain function) from any cause, if you are hypersensitive (allergic) to it, or if you have Parkinson's disease."),
    c("haloperidol", "how-to-take", DOSE, "dosage should be individualized according to the needs and response of each patient.", "Your dose should be set for you, according to your needs and how you respond."),
    c("haloperidol", "how-to-take", DOSE, "Children, debilitated or geriatric patients, as well as those with a history of adverse reactions to antipsychotic drugs, may require less haloperidol.", "Children, people who are debilitated or elderly, and people who have had side effects from antipsychotic medicines before may need less haloperidol."),
    c("haloperidol", "side-effects", ADVERSE, "EPS during the administration of haloperidol have been reported frequently, often during the first few days of treatment. EPS can be categorized generally as Parkinson-like symptoms, akathisia, or dystonia (including opisthotonos and oculogyric crisis).", "Extrapyramidal symptoms (EPS, a group of movement problems) have been reported frequently with haloperidol, often during the first few days of treatment. They include Parkinson-like symptoms, akathisia (inner restlessness) and dystonia (muscle spasms)."),
    c("haloperidol", "urgent-help", ADVERSE, "Symptoms of dystonia, prolonged abnormal contractions of muscle groups, may occur in susceptible individuals during the first few days of treatment. Dystonic symptoms include: spasm of the neck muscles, sometimes progressing to tightness of the throat, swallowing difficulty, difficulty breathing, and/or protrusion of the tongue.", "Dystonia (long muscle spasms) may occur in susceptible people during the first few days of treatment. Symptoms include spasm of the neck muscles, sometimes progressing to tightness of the throat, trouble swallowing, trouble breathing and/or the tongue sticking out."),
    c("haloperidol", "side-effects", ADVERSE, "Tardive Dyskinesia As with all antipsychotic agents, haloperidol has been associated with persistent dyskinesias. Tardive dyskinesia, a syndrome consisting of potentially irreversible, involuntary, dyskinetic movements, may appear in some patients on long-term therapy or may occur after drug therapy has been discontinued.", "Like all antipsychotics, haloperidol has been linked to persistent abnormal movements. Tardive dyskinesia is a condition of potentially irreversible, involuntary movements that may appear in some people on long-term treatment, or after the medicine has been stopped."),
    c("haloperidol", "side-effects", ADVERSE, "The syndrome is characterized by rhythmical involuntary movements of tongue, face, mouth or jaw (e.g., protrusion of tongue, puffing of cheeks, puckering of mouth, chewing movements).", "Tardive dyskinesia shows as rhythmical involuntary movements of the tongue, face, mouth or jaw, for example the tongue sticking out, puffing of the cheeks, puckering of the mouth or chewing movements."),
    c("haloperidol", "side-effects", ADVERSE, "Tachycardia, hypotension, and hypertension have been reported. QT prolongation and/or ventricular arrhythmias have also been reported, in addition to ECG pattern changes compatible with the polymorphous configuration of Torsades de pointes, and may occur more frequently with high doses and in predisposed patients", "Fast heartbeat, low blood pressure and high blood pressure have been reported. Heart rhythm changes (QT prolongation, and ventricular arrhythmias including a pattern called Torsades de pointes) have also been reported and may occur more often with high doses and in people who are predisposed to them."),
    c("haloperidol", "side-effects", ADVERSE, "Neuroleptic malignant syndrome (NMS), hyperpyrexia and heat stroke have been reported with haloperidol.", "Neuroleptic malignant syndrome (NMS, a rare, serious reaction to antipsychotics), a very high fever (hyperpyrexia) and heat stroke have been reported with haloperidol."),
    c("haloperidol", "side-effects", ADVERSE, "Anorexia, constipation, diarrhea, hypersalivation, dyspepsia, nausea and vomiting.", "Stomach and bowel effects listed: loss of appetite, constipation, diarrhoea, too much saliva, indigestion, nausea and vomiting."),
    c("haloperidol", "side-effects", ADVERSE, "Dry mouth, blurred vision, urinary retention, diaphoresis and priapism.", "Other effects listed: dry mouth, blurred vision, difficulty passing urine (urinary retention), sweating and priapism (a painful, prolonged erection)."),
    c("haloperidol", "stopping", ADVERSE, "However, some patients on maintenance treatment experience transient dyskinetic signs after abrupt withdrawal. In certain of these cases the dyskinetic movements are indistinguishable from the syndrome described below under “Tardive Dyskinesia” except for duration. It is not known whether gradual withdrawal of antipsychotic drugs will reduce the rate of occurrence of withdrawal emergent neurological signs but until further evidence becomes available, it seems reasonable to gradually withdraw use of haloperidol.", "Some people on long-term treatment get temporary abnormal movements (dyskinetic signs) after stopping suddenly. It is not known whether stopping gradually reduces this, but the label says it seems reasonable to stop haloperidol gradually. Do not stop without talking to your prescriber."),

    /* ---- chlorpromazine tablets ---- */
    c("chlorpromazine", "used-for", IND, "For the management of manifestations of psychotic disorders. For the treatment of schizophrenia. To control nausea and vomiting. For relief of restlessness and apprehension before surgery.", "Chlorpromazine is used to manage the symptoms of psychotic disorders, to treat schizophrenia, to control nausea and vomiting, and to relieve restlessness and apprehension (worry) before surgery."),
    c("chlorpromazine", "used-for", IND, "For acute intermittent porphyria. As an adjunct in the treatment of tetanus. To control the manifestations of the manic type of manic-depressive illness. For relief of intractable hiccups.", "The label also lists these uses: acute intermittent porphyria, as an add-on treatment for tetanus, to control the manic type of manic-depressive illness (bipolar disorder), and to relieve hiccups that will not stop (intractable hiccups)."),
    c("chlorpromazine", "precaution", BOX, "Elderly patients with dementia-related psychosis treated with antipsychotic drugs are at an increased risk of death.", "Elderly people with dementia-related psychosis who are treated with antipsychotic medicines are at an increased risk of death."),
    c("chlorpromazine", "contraindication", CONTRA, "Do not use in patients with known hypersensitivity to phenothiazines. Do not use in comatose states or in the presence of large amounts of central nervous system depressants (alcohol, barbiturates, narcotics, etc.).", "Do not use it if you are known to be hypersensitive (allergic) to phenothiazines (the group of medicines chlorpromazine belongs to). Do not use it in a coma, or when there are large amounts of medicines or substances in the body that slow the brain (alcohol, barbiturates, narcotics and similar)."),
    c("chlorpromazine", "onset", DOSE, "Maximum improvement may not be seen for weeks or even months.", "For psychotic disorders, the label says maximum improvement may not be seen for weeks or even months.", ["This is stated for the treatment of psychotic disorders, not for every use of chlorpromazine.", "US prescribing information, which is written for clinicians: this restates it in plain words.", "US label only: Indian approval, strengths and warnings may differ."], "onset-works-gradually"),
    c("chlorpromazine", "how-to-take", DOSE, "Adjust dosage to individual and the severity of his condition", "Your dose is adjusted to you and the severity of your condition. Your prescriber decides it, not you."),
    c("chlorpromazine", "how-to-take", DOSE, "In continued therapy, gradually reduce dosage to the lowest effective maintenance level, after symptoms have been controlled for a reasonable period.", "In continued treatment, the dose is gradually reduced to the lowest level that keeps working, once symptoms have been controlled for a reasonable period."),
    c("chlorpromazine", "how-to-take", DOSE, "In general, dosages in the lower range are sufficient for most elderly patients. Since they appear to be more susceptible to hypotension and neuromuscular reactions, such patients should be observed closely.", "Elderly people usually need doses in the lower range. They appear more susceptible to low blood pressure and muscle and nerve reactions, so they should be watched closely."),
    c("chlorpromazine", "side-effects", ADVERSE, "Usually mild to moderate, may occur, particularly during the first or second week, after which it generally disappears. If troublesome, dosage may be lowered.", "Drowsiness is usually mild to moderate and may occur, particularly in the first or second week, after which it generally goes away. If it is troublesome, the dose may be lowered."),
    c("chlorpromazine", "side-effects", ADVERSE, "Overall incidence has been low, regardless of indication or dosage. Most investigators conclude it is a sensitivity reaction. Most cases occur between the second and fourth weeks of therapy.", "Jaundice (yellowing of the skin and eyes) is uncommon. Most investigators conclude it is a sensitivity reaction, and most cases occur between the second and fourth weeks of treatment."),
    c("chlorpromazine", "side-effects", ADVERSE, "It is usually promptly reversible on withdrawal of the medication; however, chronic jaundice has been reported.", "Jaundice is usually promptly reversible when the medicine is withdrawn, but chronic (long-lasting) jaundice has been reported."),
    c("chlorpromazine", "side-effects", ADVERSE, "Hematological Disorders: including agranulocytosis, eosinophilia, leukopenia, hemolytic anemia, aplastic anemia, thrombocytopenic purpura and pancytopenia have been reported.", "Blood disorders have been reported, including agranulocytosis and leukopenia (low white blood cells), hemolytic and aplastic anemia (low red blood cells), thrombocytopenic purpura (low platelets with bruising) and pancytopenia (all blood cells low), as well as eosinophilia (raised eosinophils)."),
    c("chlorpromazine", "urgent-help", ADVERSE, "Warn patients to report the sudden appearance of sore throat or other signs of infection.", "Report the sudden appearance of a sore throat or other signs of infection to your prescriber."),
    c("chlorpromazine", "monitoring", ADVERSE, "Most cases have occurred between the fourth and tenth weeks of therapy; patients should be watched closely during that period.", "Most cases of agranulocytosis (a serious drop in white blood cells) have occurred between the fourth and tenth weeks of treatment, so you should be watched closely during that period."),
    c("chlorpromazine", "side-effects", ADVERSE, "Postural hypotension, simple tachycardia, momentary fainting and dizziness may occur rarely, after the first oral dose.", "Low blood pressure on standing (postural hypotension), a simple fast heartbeat, brief fainting and dizziness may occur, rarely, after the first oral dose."),
    c("chlorpromazine", "side-effects", ADVERSE, "Neuromuscular reactions include dystonias, motor restlessness, pseudo-parkinsonism and tardive dyskinesia, and appear to be dose-related.", "Muscle and nerve (neuromuscular) reactions include dystonias (muscle spasms), motor restlessness, pseudo-parkinsonism (Parkinson-like symptoms) and tardive dyskinesia (abnormal movements), and appear to be related to the dose."),
    c("chlorpromazine", "side-effects", ADVERSE, "Sudden death, apparently due to cardiac arrest, has been reported.", "Sudden death, apparently due to cardiac arrest (the heart stopping), has been reported."),

    /* ---- buspirone tablets ---- */
    c("buspirone", "used-for", IND, "Buspirone hydrochloride tablets are indicated for the management of anxiety disorders or the short-term relief of the symptoms of anxiety. Anxiety or tension associated with the stress of everyday life usually does not require treatment with an anxiolytic.", "Buspirone is used to manage anxiety disorders or to give short-term relief of the symptoms of anxiety. The label says anxiety or tension from the stress of everyday life usually does not need treatment with an anxiety medicine (anxiolytic)."),
    c("buspirone", "precaution", IND, "The effectiveness of buspirone hydrochloride tablets in long-term use, that is, for more than 3 to 4 weeks, has not been demonstrated in controlled trials.", "Controlled trials have not shown that buspirone keeps working when used for a long time (more than 3 to 4 weeks)."),
    c("buspirone", "monitoring", IND, "the physician who elects to use buspirone hydrochloride tablets for extended periods should periodically reassess the usefulness of the drug for the individual patient.", "If buspirone is used for a long period, your prescriber should regularly reassess whether it is still useful for you."),
    c("buspirone", "contraindication", CONTRA, "Buspirone hydrochloride tablets are contraindicated in patients hypersensitive to buspirone hydrochloride.", "Do not take it if you are known to be hypersensitive (allergic) to buspirone."),
    c("buspirone", "interactions", CONTRA, "The use of monoamine oxidase inhibitors (MAOIs) intended to treat depression with buspirone or within 14 days of stopping treatment with buspirone is contraindicated because of an increased risk of serotonin syndrome and/or elevated blood pressure. The use of buspirone within 14 days of stopping an MAOI intended to treat depression is also contraindicated.", "Do not use an MAOI antidepressant (a monoamine oxidase inhibitor) with buspirone, or within 14 days of stopping buspirone, because of an increased risk of serotonin syndrome and/or high blood pressure. Do not use buspirone within 14 days of stopping an MAOI antidepressant either."),
    c("buspirone", "how-to-take", DOSE, "The bioavailability of buspirone is increased when given with food as compared to the fasted state (see CLINICAL PHARMACOLOGY). Consequently, patients should take buspirone in a consistent manner with regard to the timing of dosing; either always with or always without food.", "Food increases how much buspirone your body takes in. So take it the same way every time: either always with food or always without food."),
    c("buspirone", "how-to-take", DOSE, "The recommended initial dose is 15 mg daily (7.5 mg b.i.d.). To achieve an optimal therapeutic response, at intervals of 2 to 3 days the dosage may be increased 5 mg per day, as needed. The maximum daily dosage should not exceed 60 mg per day.", "The label gives a recommended starting dose of 15 mg a day (7.5 mg twice a day). It may be increased by 5 mg a day every 2 to 3 days as needed, and the maximum is 60 mg a day. Your own dose is set by your prescriber.", ["US prescribing information, which is written for clinicians: this restates it in plain words.", "These are the doses in the US label. Do not use them to change your own dose.", "US label only: Indian approval, strengths and warnings may differ."]),
    c("buspirone", "side-effects", ADVERSE, "The more commonly observed untoward events associated with the use of buspirone hydrochloride tablets not seen at an equivalent incidence among placebo-treated patients include dizziness, nausea, headache, nervousness, lightheadedness, and excitement.", "The side effects more commonly seen with buspirone than with a dummy tablet (placebo) include dizziness, nausea, headache, nervousness, lightheadedness and excitement."),

    /* ---- propranolol tablets ---- */
    c("propranolol", "used-for", IND, "Propranolol hydrochloride tablets, USP are indicated in the management of hypertension. It may be used alone or used in combination with other antihypertensive agents, particularly a thiazide diuretic.", "Propranolol is used to manage high blood pressure (hypertension), alone or with other blood pressure medicines, particularly a thiazide diuretic (water tablet)."),
    c("propranolol", "used-for", IND, "Propranolol hydrochloride tablets, USP are indicated to decrease angina frequency and increase exercise tolerance in patients with angina pectoris.", "It is used to reduce how often angina (chest pain from the heart) occurs and to improve exercise tolerance in people with angina."),
    c("propranolol", "used-for", IND, "Propranolol hydrochloride tablets, USP are indicated to control ventricular rate in patients with atrial fibrillation and a rapid ventricular response.", "It is used to control the heart rate in people with atrial fibrillation (an irregular heartbeat) and a rapid ventricular response (a fast heartbeat)."),
    c("propranolol", "used-for", IND, "Propranolol hydrochloride tablets, USP are indicated to reduce cardiovascular mortality in patients who have survived the acute phase of myocardial infarction and are clinically stable.", "It is used to reduce deaths from heart and blood vessel disease in people who have survived the acute phase of a heart attack (myocardial infarction) and are clinically stable."),
    c("propranolol", "used-for", IND, "Propranolol hydrochloride tablets, USP are indicated for the prophylaxis of common migraine headache. The efficacy of propranolol in the treatment of a migraine attack that has started has not been established, and propranolol is not indicated for such use.", "It is used to prevent common migraine headaches. It has not been shown to treat a migraine attack that has already started, and it is not meant for that."),
    c("propranolol", "used-for", IND, "Propranolol hydrochloride tablets, USP are indicated in the management of familial or hereditary essential tremor.", "It is used to manage familial or hereditary essential tremor (shaking of the hands and arms that runs in families). The label says it is not for tremor caused by Parkinson's disease."),
    c("propranolol", "contraindication", CONTRA, "Propranolol is contraindicated in 1) cardiogenic shock; 2) sinus bradycardia and greater than first degree block; 3) bronchial asthma; and 4) in patients with known hypersensitivity to propranolol hydrochloride.", "Propranolol must not be used in cardiogenic shock (a failing heart that cannot supply the body), in a slow heartbeat called sinus bradycardia or in heart block beyond the first degree, in bronchial asthma, or by people who are known to be hypersensitive (allergic) to it."),
    c("propranolol", "stopping", WARN, "There have been reports of exacerbation of angina and, in some cases, myocardial infarction, following abrupt discontinuance of propranolol therapy. Therefore, when discontinuance of propranolol is planned, the dosage should be gradually reduced over at least a few weeks and the patient should be cautioned against interruption or cessation of therapy without the physician's advice.", "Angina has got worse, and in some cases a heart attack has occurred, after propranolol was stopped suddenly. When stopping is planned, the dose should be reduced gradually over at least a few weeks. Do not interrupt or stop it without your doctor's advice."),
    c("propranolol", "precaution", WARN, "In general, patients with bronchospastic lung disease should not receive beta blockers. Propranolol should be administered with caution in this setting since it may provoke a bronchial asthmatic attack by blocking bronchodilation produced by endogenous and exogenous catecholamine stimulation of beta-receptors.", "In general, people with bronchospastic lung disease (lungs that tighten and narrow the airways) should not receive beta blockers such as propranolol. If it is used, it needs caution, because it may provoke an asthma attack."),
    c("propranolol", "precaution", WARN, "Sympathetic stimulation may be a vital component supporting circulatory function in patients with congestive heart failure, and its inhibition by beta blockade may precipitate more severe failure.", "In people with congestive heart failure, the body's natural stimulation of the heart may be vital, and blocking it with a beta blocker such as propranolol may make the failure more severe."),
    c("propranolol", "precaution", WARN, "Beta-adrenergic blockade may prevent the appearance of certain premonitory signs and symptoms (pulse rate and pressure changes) of acute hypoglycemia, especially in labile insulin-dependent diabetics.", "Propranolol may hide some early warning signs of low blood sugar (changes in pulse rate and blood pressure), especially in people on insulin whose blood sugar swings widely."),
    c("propranolol", "precaution", WARN, "Chronically administered beta-blocking therapy should not be routinely withdrawn prior to major surgery, however the impaired ability of the heart to respond to reflex adrenergic stimuli may augment the risks of general anesthesia and surgical procedures.", "Long-term beta-blocker treatment should not routinely be stopped before major surgery, but the heart's weakened ability to respond to reflexes may add to the risks of general anaesthesia and surgery."),
    c("propranolol", "precaution", WARN, "Beta-adrenergic blockade may mask certain clinical signs of hyperthyroidism. Therefore, abrupt withdrawal of propranolol may be followed by an exacerbation of symptoms of hyperthyroidism, including thyroid storm.", "Propranolol may hide some signs of an overactive thyroid (hyperthyroidism). Stopping it suddenly may be followed by worse thyroid symptoms, including thyroid storm (a dangerous flare of thyroid overactivity)."),
    c("propranolol", "how-to-take", DOSE, "Because of the variable bioavailability of propranolol, the dose should be individualized based on response.", "How much of propranolol your body absorbs varies, so your dose should be individualised according to how you respond."),
    c("propranolol", "onset", DOSE, "The time needed for full antihypertensive response to a given dosage is variable and may range from a few days to several weeks.", "For high blood pressure, the label says the time needed for the full response to a given dose varies and may range from a few days to several weeks.", ["This is stated for the treatment of high blood pressure (hypertension), not for every use of propranolol.", "US prescribing information, which is written for clinicians: this restates it in plain words.", "US label only: Indian approval, strengths and warnings may differ."], "onset-works-gradually"),
    c("propranolol", "side-effects", ADVERSE, "Cardiovascular: Bradycardia; congestive heart failure; intensification of AV block; hypotension; paresthesia of hands; thrombocytopenic purpura; arterial insufficiency, usually of the Raynaud type.", "Listed effects on the heart and circulation: a slow heartbeat (bradycardia), congestive heart failure, worsening of heart block (AV block), low blood pressure, tingling in the hands, thrombocytopenic purpura (low platelets with bruising), and poor blood flow to the fingers and toes, usually of the Raynaud type.", LIST_PI),
    c("propranolol", "side-effects", ADVERSE, "Central Nervous System: Light-headedness, mental depression manifested by insomnia, lassitude, weakness, fatigue; catatonia; visual disturbances; hallucinations; vivid dreams;", "Listed effects on the brain and nerves: light-headedness; mental depression with insomnia, lack of energy (lassitude), weakness and tiredness; catatonia; visual disturbances; hallucinations; and vivid dreams.", LIST_PI),
    c("propranolol", "side-effects", ADVERSE, "Gastrointestinal: Nausea, vomiting, epigastric distress, abdominal cramping, diarrhea, constipation,", "Listed effects on the stomach and bowel: nausea, vomiting, upper stomach discomfort, abdominal cramps, diarrhoea and constipation.", LIST_PI),
    c("propranolol", "side-effects", ADVERSE, "Respiratory: Bronchospasm.", "Listed effect on the lungs: bronchospasm (tightening of the airways).", LIST_PI),

    /* ---- clonidine tablets ---- */
    c("clonidine", "used-for", IND, "Clonidine hydrochloride is indicated in the treatment of hypertension. Clonidine hydrochloride may be employed alone or concomitantly with other antihypertensive agents.", "This label for clonidine tablets says it is used to treat high blood pressure (hypertension), alone or with other blood pressure medicines. It does not describe other uses of clonidine.", ["This is the label for clonidine tablets for high blood pressure. Other uses and forms of clonidine are not covered.", "US prescribing information, which is written for clinicians: this restates it in plain words.", "US label only: Indian approval, strengths and warnings may differ."]),
    c("clonidine", "contraindication", CONTRA, "Clonidine hydrochloride tablets USP should not be used in patients with known hypersensitivity to clonidine", "Clonidine tablets should not be used if you are known to be hypersensitive (allergic) to clonidine."),
    c("clonidine", "stopping", WARN, "Patients should be instructed not to discontinue therapy without consulting their physician. Sudden cessation of clonidine treatment has, in some cases, resulted in symptoms such as nervousness, agitation, headache, and tremor accompanied or followed by a rapid rise in blood pressure and elevated catecholamine concentrations in the plasma.", "Do not stop clonidine without consulting your doctor. Stopping suddenly has, in some cases, caused nervousness, agitation, headache and tremor, accompanied or followed by a rapid rise in blood pressure."),
    c("clonidine", "stopping", WARN, "Rare instances of hypertensive encephalopathy, cerebrovascular accidents and death have been reported after clonidine withdrawal. When discontinuing therapy with clonidine hydrochloride, the physician should reduce the dose gradually over 2 to 4 days to avoid withdrawal symptomatology.", "Rare cases of hypertensive encephalopathy (brain swelling from very high blood pressure), stroke (cerebrovascular accidents) and death have been reported after clonidine was withdrawn. When stopping, the doctor should reduce the dose gradually over 2 to 4 days to avoid withdrawal symptoms."),
    c("clonidine", "interactions", WARN, "The likelihood of such reactions to discontinuation of clonidine therapy appears to be greater after administration of higher doses or continuation of concomitant beta-blocker treatment and special caution is therefore advised in these situations.", "Reactions to stopping clonidine seem more likely after higher doses, or if a beta-blocker (another type of blood pressure medicine) is continued at the same time, so special caution is advised in these situations."),
    c("clonidine", "precaution", PC, "Since patients may experience a possible sedative effect, dizziness, or accommodation disorder with use of clonidine, caution patients about engaging in activities such as driving a vehicle or operating appliances or machinery. Also, inform patients that this sedative effect may be increased by concomitant use of alcohol, barbiturates, or other sedating drugs.", "Clonidine can cause sedation (sleepiness), dizziness or trouble focusing the eyes (accommodation disorder), so be careful with activities such as driving or operating appliances or machinery. The sleepiness may be increased if you also use alcohol, barbiturates or other sedating medicines."),
    c("clonidine", "precaution", PC, "Patients who wear contact lenses should be cautioned that treatment with clonidine hydrochloride may cause dryness of eyes.", "If you wear contact lenses, be aware that clonidine may cause dry eyes."),
    c("clonidine", "how-to-take", DOSE, "The dose of clonidine hydrochloride USP must be adjusted according to the patient's individual blood pressure response.", "Your dose is adjusted according to your own blood pressure response. Your prescriber decides it, not you."),
    c("clonidine", "how-to-take", DOSE, "Taking the larger portion of the oral daily dose at bedtime may minimize transient adjustment effects of dry mouth and drowsiness.", "Taking the larger part of the daily dose at bedtime may reduce the temporary dry mouth and drowsiness while your body adjusts."),
    c("clonidine", "side-effects", ADVERSE, "Most adverse effects are mild and tend to diminish with continued therapy. The most frequent (which appear to be dose-related) are dry mouth, occurring in about 40 of 100 patients; drowsiness, about 33 in 100; dizziness, about 16 in 100; constipation and sedation, each about 10 in 100.", "Most side effects are mild and tend to lessen with continued treatment. The most frequent, which appear to depend on the dose, are dry mouth (about 40 in 100 patients), drowsiness (about 33 in 100), dizziness (about 16 in 100), and constipation and sedation (each about 10 in 100).", ["US prescribing information, which is written for clinicians: this restates it in plain words.", "Figures come from US studies and cannot predict how common a side effect is for any one person.", "US label only: Indian approval, strengths and warnings may differ."]),

    /* ---- hydroxyzine tablets ---- */
    c("hydroxyzine", "used-for", IND, "For symptomatic relief of anxiety and tension associated with psychoneurosis and as an adjunct in organic disease states in which anxiety is manifested.", "Hydroxyzine is used for symptomatic relief of anxiety and tension associated with psychoneurosis (an older medical term for anxiety-related conditions), and as an add-on in physical illnesses in which anxiety shows."),
    c("hydroxyzine", "used-for", IND, "Useful in the management of pruritus due to allergic conditions such as chronic urticaria and atopic and contact dermatoses and in histamine-mediated pruritus.", "It is useful for managing itching (pruritus) caused by allergic conditions such as chronic hives (urticaria) and eczema-type skin conditions (atopic and contact dermatoses), and itching caused by histamine."),
    c("hydroxyzine", "used-for", IND, "As a sedative when used as a premedication and following general anesthesia,", "It is also used as a sedative before and after general anaesthesia."),
    c("hydroxyzine", "precaution", IND, "The effectiveness of hydroxyzine as an antianxiety agent for long term use, that is more than 4 months, has not been assessed by systematic clinical studies. The physician should reassess periodically the usefulness of the drug for the individual patient.", "Studies have not systematically assessed how well hydroxyzine works as an anti-anxiety medicine over long use (more than 4 months). Your prescriber should reassess from time to time whether it is still useful for you."),
    c("hydroxyzine", "contraindication", CONTRA, "Oral hydroxyzine hydrochloride is contraindicated in patients with known hypersensitivity to hydroxyzine hydrochloride products, and in patients with known hypersensitivity to cetirizine hydrochloride or levocetirizine hydrochloride. Hydroxyzine is contraindicated in patients with a prolonged QT interval.", "Do not take oral hydroxyzine if you are known to be hypersensitive (allergic) to hydroxyzine products, cetirizine or levocetirizine, or if you have a prolonged QT interval (a heart rhythm change seen on an ECG)."),
    c("hydroxyzine", "contraindication", CONTRA, "Clinical data in human beings are inadequate to establish safety in early pregnancy. Until such data are available, hydroxyzine is contraindicated in early pregnancy.", "There are not enough data in people to show that hydroxyzine is safe in early pregnancy, so it must not be used in early pregnancy."),
    c("hydroxyzine", "precaution", WARN, "It is not known whether this drug is excreted in human milk. Since many drugs are so excreted, hydroxyzine should not be given to nursing mothers.", "It is not known whether hydroxyzine passes into breast milk. Because many medicines do, it should not be given to nursing mothers."),
    c("hydroxyzine", "how-to-take", DOSE, "As with all potent medication, the dosage should be adjusted according to the patient’s response to therapy.", "As with all potent medicines, the dose should be adjusted according to how you respond. Your prescriber decides it, not you."),
    c("hydroxyzine", "side-effects", ADVERSE, "Side effects reported with the administration of hydroxyzine hydrochloride are usually mild and transitory in nature. Anticholinergic: Dry mouth. Central Nervous System: Drowsiness is usually transitory and may disappear in a few days of continued therapy or upon reduction of dose.", "Side effects are usually mild and short-lived. Dry mouth can occur. Drowsiness is usually temporary and may disappear within a few days of continued treatment, or when the dose is reduced."),
    c("hydroxyzine", "side-effects", ADVERSE, "Involuntary motor activity including rare instances of tremor and convulsions have been reported, usually with doses considerably higher than those recommended.", "Involuntary movements, including rare cases of tremor and convulsions (fits), have been reported, usually with doses much higher than those recommended."),
    c("hydroxyzine", "side-effects", ADVERSE, "Cardiac System: QT prolongation, Torsade de Pointes.", "Heart rhythm changes have been reported: QT prolongation and Torsade de Pointes (a dangerous irregular heart rhythm)."),
    c("hydroxyzine", "side-effects", ADVERSE, "Oral hydroxyzine is associated with Acute Generalized Exanthematous Pustulosis (AGEP) and fixed drug eruptions in postmarketing reports; pruritus, rash, urticaria.", "Reports after the medicine was on the market link oral hydroxyzine to skin reactions: acute generalized exanthematous pustulosis (AGEP, a sudden widespread rash with small pus-filled spots), fixed drug eruptions (a rash that returns in the same place), itching, rash and hives (urticaria)."),

    /* ---- trihexyphenidyl tablets ---- */
    c("trihexyphenidyl", "used-for", IND, "This drug is indicated as an adjunct in the treatment of all forms of parkinsonism (postencephalitic, arteriosclerotic, and idiopathic). It is often useful as adjuvant therapy when treating these forms of parkinsonism with levodopa.", "Trihexyphenidyl is used as an add-on treatment for all forms of parkinsonism (postencephalitic, arteriosclerotic and idiopathic). It is often useful as an add-on when these forms are treated with levodopa."),
    c("trihexyphenidyl", "used-for", IND, "Additionally, it is indicated for the control of extrapyramidal disorders caused by central nervous system drugs such as the dibenzoxazepines, phenothiazines, thioxanthenes, and butyrophenones.", "It is also used to control extrapyramidal disorders (movement problems) caused by medicines that act on the brain, such as dibenzoxazepines, phenothiazines, thioxanthenes and butyrophenones (groups of antipsychotic medicines)."),
    c("trihexyphenidyl", "precaution", WARN, "Patients to be treated with trihexyphenidyl HCl should have a gonioscope evaluation and close monitoring of intraocular pressures at regular periodic intervals.", "People treated with trihexyphenidyl should have an eye examination (gonioscopy) and regular, close checks of the pressure inside the eye."),
    c("trihexyphenidyl", "precaution", ADVERSE, "Patients with arteriosclerosis or with a history of idiosyncrasy to other drugs may exhibit reactions of mental confusion, agitation, disturbed behavior, or nausea and vomiting.", "People with arteriosclerosis (hardened arteries), or who have reacted unusually to other medicines before, may get mental confusion, agitation, disturbed behaviour, or nausea and vomiting."),
    c("trihexyphenidyl", "precaution", ADVERSE, "Psychiatric disturbances can result from indiscriminate use (leading to overdosage) to sustain continued euphoria.", "Psychiatric disturbances can result from using it carelessly (leading to overdose) to keep up a feeling of euphoria."),
    c("trihexyphenidyl", "how-to-take", DOSE, "Dosage should be individualized. The initial dose should be low and then increased gradually, especially in patients over 60 years of age.", "Your dose should be set for you. It should start low and be increased gradually, especially in people over 60 years of age."),
    c("trihexyphenidyl", "how-to-take", DOSE, "Whether trihexyphenidyl HCl may best be given before or after meals should be determined by the way the patient reacts.", "Whether it is best taken before or after meals depends on how you react to it."),
    c("trihexyphenidyl", "how-to-take", DOSE, "If trihexyphenidyl HCl tends to dry the mouth excessively, it may be better to take it before meals, unless it causes nausea. If taken after meals, the thirst sometimes induced can be allayed by mint candies, chewing gum or water.", "If it dries your mouth too much, it may be better to take it before meals, unless it causes nausea. If you take it after meals, any thirst it causes can be eased with mint candies, chewing gum or water."),
    c("trihexyphenidyl", "side-effects", ADVERSE, "Minor side effects, such as dryness of the mouth, blurring of vision, dizziness, mild nausea, or nervousness, will be experienced by 30 to 50 percent of all patients.", "Minor side effects such as dry mouth, blurred vision, dizziness, mild nausea or nervousness will be experienced by 30 to 50 percent of patients."),
    c("trihexyphenidyl", "side-effects", ADVERSE, "Such reactions tend to become less pronounced, and even to disappear, as treatment continues. Even before these reactions have remitted spontaneously, they may often be controlled by careful adjustment of the dosage form, amount of drug, or interval between doses.", "These reactions tend to become less pronounced, and even to disappear, as treatment continues. Even before they ease on their own, they can often be controlled by carefully adjusting the dosage form, the amount of medicine, or the time between doses."),
    c("trihexyphenidyl", "side-effects", ADVERSE, "Potential side effects associated with the use of any atropine-like drugs include constipation, drowsiness, urinary hesitancy or retention, tachycardia, dilation of the pupil, increased intraocular tension, weakness, vomiting, and headache.", "Side effects possible with any atropine-like (drying) medicine include constipation, drowsiness, difficulty starting to pass urine or not being able to pass it, a fast heartbeat, widened pupils, raised pressure in the eye, weakness, vomiting and headache."),
    c("trihexyphenidyl", "side-effects", ADVERSE, "The occurrence of angle-closure glaucoma due to long-term treatment with trihexyphenidyl hydrochloride has been reported.", "Angle-closure glaucoma (a sudden rise of eye pressure) has been reported with long-term treatment."),
    c("trihexyphenidyl", "side-effects", ADVERSE, "Isolated instances of suppurative parotitis secondary to excessive dryness of the mouth, skin rashes, dilatation of the colon, paralytic ileus, and certain psychiatric manifestations such as delusions and hallucinations, plus one doubtful case of paranoia all of which may occur with any of the atropine-like drugs, have been rarely reported with trihexyphenidyl hydrochloride.", "Rarely reported: infection of the salivary gland (suppurative parotitis) from a very dry mouth, skin rashes, widening of the colon, a blocked bowel (paralytic ileus), and psychiatric effects such as delusions and hallucinations, plus one doubtful case of paranoia. All of these may occur with any atropine-like drug."),

    /* ---- benztropine tablets ---- */
    c("benztropine", "used-for", IND, "For use as an adjunct in the therapy of all forms of parkinsonism.", "Benztropine is used as an add-on treatment for all forms of parkinsonism."),
    c("benztropine", "used-for", IND, "Useful also in the control of extrapyramidal disorders (except tardive dyskinesia", "It is also useful for controlling extrapyramidal disorders (movement problems), but the label excepts tardive dyskinesia."),
    c("benztropine", "used-for", IND, "due to neuroleptic drugs (e.g., phenothiazines).", "The movement problems it is used for are those caused by neuroleptic (antipsychotic) drugs, for example phenothiazines."),
    c("benztropine", "contraindication", CONTRA, "Hypersensitivity to benztropine mesylate tablets. Because of its atropine-like side effects, this drug is contraindicated in pediatric patients under three years of age, and should be used with caution in older pediatric patients.", "Do not take it if you are hypersensitive (allergic) to benztropine tablets. Because of its atropine-like side effects, it must not be given to children under three years of age and needs caution in older children."),
    c("benztropine", "precaution", WARN, "Safe use in pregnancy has not been established.", "Safe use in pregnancy has not been established."),
    c("benztropine", "precaution", WARN, "Benztropine mesylate may impair mental and/or physical abilities required for performance of hazardous tasks, such as operating machinery or driving a motor vehicle.", "It may impair the mental and/or physical abilities needed for hazardous tasks such as operating machinery or driving."),
    c("benztropine", "urgent-help", WARN, "When benztropine mesylate is given concomitantly with phenothiazines, haloperidol, or other drugs with anticholinergic or antidopaminergic activity, patients should be advised to report gastrointestinal complaints, fever or heat intolerance promptly.", "If you take benztropine with phenothiazines, haloperidol or other medicines with drying (anticholinergic) or dopamine-blocking (antidopaminergic) effects, report stomach and bowel complaints, fever or heat intolerance promptly."),
    c("benztropine", "side-effects", WARN, "Paralytic ileus, hyperthermia and heat stroke, all of which have sometimes been fatal, have occurred in patients taking anticholinergic-type antiparkinsonism drugs, including benztropine mesylate, in combination with phenothiazines and/or tricyclic antidepressants.", "A blocked bowel (paralytic ileus), a very high body temperature (hyperthermia) and heat stroke, all of which have sometimes been fatal, have occurred in people taking drying (anticholinergic) anti-parkinsonism medicines, including benztropine, together with phenothiazines and/or tricyclic antidepressants."),
    c("benztropine", "precaution", WARN, "Since benztropine mesylate contains structural features of atropine, it may produce anhidrosis. For this reason, it should be administered with caution during hot weather, especially when given concomitantly with other atropine-like drugs to the chronically ill, the alcoholic, those who have central nervous system disease, and those who do manual labor in a hot environment.", "Because it is built like atropine, benztropine may stop you sweating (anhidrosis). It needs caution in hot weather, especially with other atropine-like drugs, in people who are chronically ill or alcoholic, who have central nervous system disease, or who do manual labour in a hot place."),
    c("benztropine", "how-to-take", DOSE, "Because of cumulative action, therapy should be initiated with a low dose which is increased gradually at five- or six-day intervals to the smallest amount necessary for optimal relief.", "Because the effect builds up, treatment should start with a low dose that is increased gradually at five- or six-day intervals to the smallest amount needed for the best relief."),
    c("benztropine", "how-to-take", DOSE, "Some patients experience greatest relief by taking the entire dose at bedtime; others react more favorably to divided doses, two to four times a day.", "Some people get the greatest relief taking the whole dose at bedtime; others do better with divided doses two to four times a day."),
    c("benztropine", "side-effects", ADVERSE, "Digestive Paralytic ileus, constipation, vomiting, nausea, dry mouth.", "Digestive effects listed: a blocked bowel (paralytic ileus), constipation, vomiting, nausea and dry mouth."),
    c("benztropine", "monitoring", ADVERSE, "If dry mouth is so severe that there is difficulty in swallowing or speaking, or loss of appetite and weight, reduce dosage or discontinue the drug temporarily.", "If dry mouth is so severe that you have difficulty swallowing or speaking, or lose appetite and weight, tell your prescriber: the label says to reduce the dose or stop the medicine temporarily."),
    c("benztropine", "side-effects", ADVERSE, "Toxic psychosis, including confusion, disorientation, memory impairment, visual hallucinations; exacerbation of pre-existing psychotic symptoms; nervousness; depression; listlessness; numbness of fingers.", "Nervous system effects listed: toxic psychosis (including confusion, disorientation, memory impairment and visual hallucinations), worsening of existing psychotic symptoms, nervousness, depression, listlessness and numbness of the fingers."),
    c("benztropine", "side-effects", ADVERSE, "Special Senses Blurred vision, dilated pupils. Urogenital Urinary retention, dysuria.", "Listed effects on the eyes and bladder: blurred vision, widened pupils, urinary retention (not being able to pass urine) and dysuria (painful passing of urine)."),

    /* ---- disulfiram tablets ---- */
    c("disulfiram", "used-for", IND, "Disulfiram is an aid in the management of selected chronic alcohol patients who want to remain in a state of enforced sobriety so that supportive and psychotherapeutic treatment may be applied to best advantage. Disulfiram is not a cure for alcoholism.", "Disulfiram is an aid for some people with long-term alcohol problems who want to stay sober, so that supportive treatment and counselling can be used to best effect. The label says it is not a cure for alcoholism."),
    c("disulfiram", "precaution", IND, "When used alone, without proper motivation and supportive therapy, it is unlikely that it will have any substantive effect on the drinking pattern of the chronic alcoholic.", "Used alone, without proper motivation and supportive treatment, it is unlikely to have any real effect on the drinking pattern of a person with a long-term alcohol problem."),
    c("disulfiram", "precaution", BOX, "Disulfiram should never be administered to a patient when he is in a state of alcohol intoxication, or without his full knowledge. The physician should instruct relatives accordingly.", "Disulfiram should never be given to a person who is drunk, or without that person's full knowledge. The doctor should instruct relatives accordingly."),
    c("disulfiram", "precaution", WARN, "The patient must be fully informed of the disulfiram-alcohol reaction. He must be strongly cautioned against surreptitious drinking while taking the drug, and he must be fully aware of the possible consequences. He should be warned to avoid alcohol in disguised forms, i.e., in sauces, vinegars, cough mixtures, and even in aftershave lotions and back rubs. He should also be warned that reactions may occur with alcohol up to 14 days after ingesting disulfiram.", "You must be fully informed about the disulfiram-alcohol reaction and strongly cautioned against secret drinking while taking it. Avoid alcohol in disguised forms: in sauces, vinegars, cough mixtures, and even aftershave lotions and back rubs. Reactions may occur with alcohol up to 14 days after taking disulfiram."),
    c("disulfiram", "urgent-help", WARN, "Disulfiram plus alcohol, even small amounts, produce flushing, throbbing in head and neck, throbbing headache, respiratory difficulty, nausea, copious vomiting, sweating, thirst, chest pain, palpitation, dyspnea, hyperventilation, tachycardia, hypotension, syncope, marked uneasiness, weakness, vertigo, blurred vision, and confusion. In severe reactions there may be respiratory depression, cardiovascular collapse, arrhythmias, myocardial infarction, acute congestive heart failure, unconsciousness, convulsions, and death.", "Disulfiram with alcohol, even in small amounts, causes flushing, throbbing in the head and neck, a throbbing headache, trouble breathing, nausea, heavy vomiting, sweating, thirst, chest pain, a pounding heart, shortness of breath, fast breathing, a fast heartbeat, low blood pressure, fainting, marked uneasiness, weakness, vertigo, blurred vision and confusion. Severe reactions may include slowed breathing, collapse of the circulation, irregular heartbeat, heart attack, heart failure, loss of consciousness, convulsions and death."),
    c("disulfiram", "side-effects", WARN, "The duration of the reaction varies from 30 to 60 minutes, to several hours in the more severe cases, or as long as there is alcohol in the blood.", "The reaction lasts from 30 to 60 minutes, to several hours in the more severe cases, or as long as there is alcohol in the blood."),
    c("disulfiram", "contraindication", CONTRA, "Disulfiram is contraindicated in the presence of severe myocardial disease or coronary occlusion, psychoses, and hypersensitivity to disulfiram or to other thiuram derivatives used in pesticides and rubber vulcanization.", "Disulfiram must not be used if you have severe heart muscle disease or a blocked coronary artery, a psychosis, or hypersensitivity (allergy) to disulfiram or to other thiuram chemicals used in pesticides and rubber making."),
    c("disulfiram", "interactions", CONTRA, "Patients who are receiving or have recently received metronidazole, paraldehyde, alcohol, or alcohol-containing preparations, e.g., cough syrups, tonics and the like, should not be given disulfiram.", "Disulfiram should not be given to people who are receiving, or have recently received, metronidazole, paraldehyde, alcohol, or alcohol-containing preparations such as cough syrups and tonics."),
    c("disulfiram", "precaution", WARN, "Because of the possibility of an accidental disulfiram-alcohol reaction, disulfiram should be used with extreme caution in patients with any of the following conditions: diabetes mellitus, hypothyroidism, epilepsy, cerebral damage, chronic and acute nephritis, hepatic cirrhosis or insufficiency.", "Because an accidental disulfiram-alcohol reaction is possible, disulfiram should be used with extreme caution in people with diabetes, an underactive thyroid (hypothyroidism), epilepsy, brain damage, kidney inflammation (nephritis), or cirrhosis or weak function of the liver."),
    c("disulfiram", "interactions", INTER, "Disulfiram appears to decrease the rate at which certain drugs are metabolized and therefore may increase the blood levels and the possibility of clinical toxicity of drugs given concomitantly.", "Disulfiram appears to slow how fast the body breaks down some medicines, so it may raise their levels in the blood and the chance that they become toxic."),
    c("disulfiram", "interactions", INTER, "DISULFIRAM SHOULD BE USED WITH CAUTION IN THOSE PATIENTS RECEIVING PHENYTOIN AND ITS CONGENERS, SINCE THE CONCOMITANT ADMINISTRATION OF THESE TWO DRUGS CAN LEAD TO PHENYTOIN INTOXICATION.", "Disulfiram should be used with caution in people taking phenytoin and similar medicines, because taking them together can lead to phenytoin poisoning."),
    c("disulfiram", "interactions", INTER, "It may be necessary to adjust the dosage of oral anticoagulants upon beginning or stopping disulfiram, since disulfiram may prolong prothrombin time.", "The dose of oral anticoagulants (blood thinners) may need adjusting when disulfiram is started or stopped, because disulfiram may lengthen the prothrombin time (a blood clotting test)."),
    c("disulfiram", "interactions", INTER, "Patients taking isoniazid when disulfiram is given should be observed for the appearance of unsteady gait or marked changes in mental status, the disulfiram should be discontinued if such signs appear.", "People taking isoniazid together with disulfiram should be watched for an unsteady walk or marked changes in mental state; disulfiram should be stopped if such signs appear."),
    c("disulfiram", "how-to-take", DOSE, "Disulfiram should never be administered until the patient has abstained from alcohol for at least 12 hours.", "Disulfiram should never be started until the person has avoided alcohol for at least 12 hours."),
    c("disulfiram", "how-to-take", DOSE, "Although usually taken in the morning, disulfiram may be taken on retiring by patients who experience a sedative effect.", "It is usually taken in the morning, but people who feel sleepy from it may take it at bedtime."),
    c("disulfiram", "how-to-take", DOSE, "The daily, uninterrupted administration of disulfiram must be continued until the patient is fully recovered socially and a basis for permanent self-control is established. Depending on the individual patient, maintenance therapy may be required for months or even years.", "Disulfiram must be taken every day, without interruption, until the person has fully recovered socially and a basis for permanent self-control is established. Depending on the person, treatment may be needed for months or even years."),
    c("disulfiram", "side-effects", ADVERSE, "OPTIC NEURITIS, PERIPHERAL NEURITIS, POLYNEURITIS, AND PERIPHERAL NEUROPATHY MAY OCCUR FOLLOWING ADMINISTRATION OF DISULFIRAM.", "Optic neuritis (inflammation of the nerve of the eye), peripheral neuritis, polyneuritis and peripheral neuropathy (damage or inflammation of nerves in the arms and legs) may occur after taking disulfiram."),
    c("disulfiram", "urgent-help", ADVERSE, "Multiple cases of hepatitis, including both cholestatic and fulminant hepatitis, as well as hepatic failure resulting in transplantation or death, have been reported with administration of disulfiram.", "Many cases of hepatitis (inflammation of the liver), including cholestatic hepatitis and fulminant (sudden, severe) hepatitis, as well as liver failure leading to a transplant or death, have been reported with disulfiram."),
    c("disulfiram", "side-effects", ADVERSE, "In a small number of patients, a transient mild drowsiness, fatigability, impotence, headache, acneform eruptions, allergic dermatitis, or a metallic or garlic-like aftertaste may be experienced during the first two weeks of therapy. These complaints usually disappear spontaneously with the continuation of therapy, or with reduced dosage.", "In a small number of people, mild and temporary drowsiness, tiredness, impotence, headache, acne-like spots, allergic skin inflammation, or a metallic or garlic-like aftertaste may occur during the first two weeks. These complaints usually disappear on their own as treatment continues, or with a lower dose."),
    c("disulfiram", "side-effects", ADVERSE, "Psychotic reactions have been noted, attributable in most cases to high dosage, combined toxicity (with metronidazole or isoniazid), or to the unmasking of underlying psychoses in patients stressed by the withdrawal of alcohol.", "Psychotic reactions have been noted, in most cases linked to high doses, to combined toxicity with metronidazole or isoniazid, or to the unmasking of an underlying psychosis in people stressed by stopping alcohol."),

    /* ---- prazosin capsules ---- */
    c("prazosin", "used-for", IND, "Prazosin hydrochloride capsules, USP are indicated for the treatment of hypertension, to lower blood pressure.", "This label for prazosin capsules says they are used to treat high blood pressure (hypertension), to lower it. It does not describe other uses of prazosin.", ["This is the label for prazosin capsules for high blood pressure. Other uses are not covered.", "US prescribing information, which is written for clinicians: this restates it in plain words.", "US label only: Indian approval, strengths and warnings may differ."]),
    c("prazosin", "contraindication", CONTRA, "Prazosin hydrochloride capsules are contraindicated in patients with known sensitivity to quinazolines, prazosin, or any of the inert ingredients.", "Prazosin capsules must not be used by people with known sensitivity (allergy) to quinazolines, to prazosin, or to any of the inactive ingredients."),
    c("prazosin", "precaution", PC, "Dizziness or drowsiness may occur after the first dose of this medicine. Avoid driving or performing hazardous tasks for the first 24 hours after taking this medicine or when the dose is increased. Dizziness, light headedness, or fainting may occur, especially when rising from a lying or sitting position. Getting up slowly may help lessen the problem.", "Dizziness or drowsiness may occur after the first dose. Avoid driving or doing hazardous tasks for the first 24 hours after taking it, and again when the dose is increased. Dizziness, light-headedness or fainting may occur, especially when getting up from lying or sitting. Getting up slowly may help."),
    c("prazosin", "precaution", PC, "These effects may also occur if you drink alcohol, stand for long periods of time, exercise, or if the weather is hot. While taking prazosin hydrochloride capsules, be careful in the amount of alcohol you drink. Also, use extra care during exercise or hot weather, or if standing for long periods.", "These effects may also occur if you drink alcohol, stand for long periods, exercise, or if the weather is hot. Be careful how much alcohol you drink, and take extra care during exercise, in hot weather, or when standing for long periods."),
    c("prazosin", "urgent-help", WARN, "prazosin hydrochloride capsules may cause syncope with sudden loss of consciousness.", "Prazosin may cause syncope (fainting), with a sudden loss of consciousness."),
    c("prazosin", "side-effects", WARN, "Syncopal episodes have usually occurred within 30 to 90 minutes of the initial dose of the drug; occasionally, they have been reported in association with rapid dosage increases or the introduction of another antihypertensive drug into the regimen of a patient taking high doses of prazosin hydrochloride capsules.", "Fainting episodes have usually occurred within 30 to 90 minutes of the first dose. Occasionally they have been reported with rapid dose increases, or when another blood pressure medicine was added in a person taking high doses of prazosin."),
    c("prazosin", "precaution", WARN, "The patient should also be cautioned to avoid situations where injury could result should syncope occur during the initiation of prazosin hydrochloride therapy.", "Avoid situations where you could be injured if you faint when starting prazosin."),
    c("prazosin", "how-to-take", WARN, "Patients should always be started on the 1 mg capsules of prazosin hydrochloride. The 2 and 5 mg capsules are not indicated for initial therapy.", "Treatment should always be started with the 1 mg capsules. The 2 mg and 5 mg capsules are not meant for starting treatment."),
    c("prazosin", "how-to-take", DOSE, "The dose of prazosin hydrochloride capsules should be adjusted according to the patient’s individual blood pressure response.", "Your dose is adjusted according to your own blood pressure response. Your prescriber decides it, not you."),
    c("prazosin", "urgent-help", WARN, "Prolonged erections and priapism have been reported with alpha-1 blockers including prazosin in post-marketing experience. In the event of an erection that persists longer than 4 hours, seek immediate medical assistance.", "Prolonged erections and priapism (a painful, lasting erection) have been reported with alpha-1 blockers including prazosin. If an erection lasts longer than 4 hours, seek immediate medical help."),
    c("prazosin", "interactions", WARN, "Hypotension may develop in patients given prazosin hydrochloride capsules who are also receiving a beta-blocker such as propranolol.", "Low blood pressure may develop in people taking prazosin together with a beta-blocker such as propranolol."),
    c("prazosin", "interactions", INTER, "Addition of a diuretic or other antihypertensive agent to prazosin hydrochloride has been shown to cause an additive hypotensive effect.", "Adding a diuretic (water tablet) or another blood pressure medicine to prazosin has been shown to lower blood pressure further."),
    c("prazosin", "interactions", INTER, "Concomitant administration of prazosin hydrochloride with a phosphodiesterase-5 (PDE-5) inhibitor can result in additive blood pressure lowering effects and symptomatic hypotension", "Taking prazosin together with a phosphodiesterase-5 (PDE-5) inhibitor (a type of medicine for erection problems) can lower blood pressure further and cause low blood pressure with symptoms."),
    c("prazosin", "side-effects", ADVERSE, "the most frequent reactions associated with prazosin hydrochloride capsules therapy are: dizziness 10.3%, headache 7.8%, drowsiness 7.6%, lack of energy 6.9%, weakness 6.5%, palpitations 5.3%, and nausea 4.9%. In most instances, side effects have disappeared with continued therapy or have been tolerated with no decrease in dose of drug.", "The most frequent side effects were dizziness (10.3%), headache (7.8%), drowsiness (7.6%), lack of energy (6.9%), weakness (6.5%), palpitations (5.3%) and nausea (4.9%). In most cases side effects disappeared with continued treatment or were tolerated without lowering the dose.", ["US prescribing information, which is written for clinicians: this restates it in plain words.", "Figures come from US trials and cannot predict how common a side effect is for any one person.", "US label only: Indian approval, strengths and warnings may differ."]),

    /* ---- fluphenazine tablets ---- */
    c("fluphenazine", "used-for", IND, "Fluphenazine hydrochloride tablets are indicated in the management of manifestations of psychotic disorders.", "Fluphenazine is used in the management of the symptoms of psychotic disorders."),
    c("fluphenazine", "precaution", IND, "Fluphenazine hydrochloride has not been shown effective in the management of behavioral complications in patients with mental retardation.", "It has not been shown to work for behavioural complications in people with intellectual disability (the label's term is mental retardation)."),
    c("fluphenazine", "precaution", BOX, "Elderly patients with dementia-related psychosis treated with antipsychotic drugs are at an increased risk of death.", "Elderly people with dementia-related psychosis who are treated with antipsychotic medicines are at an increased risk of death. The label says fluphenazine is not approved for treating dementia-related psychosis."),
    c("fluphenazine", "contraindication", CONTRA, "Phenothiazines are contraindicated in patients with suspected or established subcortical brain damage, in patients receiving large doses of hypnotics, and in comatose or severely depressed states. The presence of blood dyscrasia or liver damage precludes the use of fluphenazine hydrochloride. Fluphenazine hydrochloride tablets are contraindicated in patients who have shown hypersensitivity to fluphenazine; cross-sensitivity to phenothiazine derivatives may occur.", "Phenothiazines (the group fluphenazine belongs to) must not be used in people with suspected or established brain damage deep in the brain (subcortical brain damage), people receiving large doses of sleeping medicines (hypnotics), or people in a coma or severely depressed state. A blood disorder (blood dyscrasia) or liver damage rules out fluphenazine. It must not be used by people who have shown hypersensitivity (allergy) to it, and an allergy to other phenothiazines may carry over."),
    c("fluphenazine", "how-to-take", DOSE, "The smallest amount that will produce the desired results must be carefully determined for each individual, since optimal dosage levels of this potent drug vary from patient to patient.", "The smallest dose that gives the desired results must be carefully worked out for each person, because the best dose of this potent medicine varies from person to person."),
    c("fluphenazine", "how-to-take", DOSE, "Treatment is best instituted with a low initial dosage, which may be increased, if necessary, until the desired clinical effects are achieved.", "Treatment is best started with a low dose, which may be increased if necessary until the desired effects are reached."),
    c("fluphenazine", "how-to-take", DOSE, "When symptoms are controlled, dosage can generally be reduced gradually to daily maintenance doses of 1 mg to 5 mg, often given as a single daily dose. Continued treatment is needed to achieve maximum therapeutic benefits", "When symptoms are controlled, the dose can generally be reduced gradually to a daily maintenance dose of 1 mg to 5 mg, often given as a single daily dose. Continued treatment is needed to get the maximum benefit. Your own dose is set by your prescriber.", ["US prescribing information, which is written for clinicians: this restates it in plain words.", "These are the figures in the US label. Do not use them to change your own dose.", "US label only: Indian approval, strengths and warnings may differ."]),
    c("fluphenazine", "side-effects", ADVERSE, "The side effects most frequently reported with phenothiazine compounds are extrapyramidal symptoms including pseudoparkinsonism, dystonia, dyskinesia, akathisia, oculogyric crises, opisthotonos, and hyperreflexia. Most often these extrapyramidal symptoms are reversible; however, they may be persistent", "The side effects most often reported with phenothiazines are extrapyramidal symptoms (movement problems): pseudoparkinsonism (Parkinson-like symptoms), dystonia (muscle spasms), dyskinesia (abnormal movements), akathisia (inner restlessness), oculogyric crises (the eyes turning upward), opisthotonos (arching of the back) and hyperreflexia (overactive reflexes). Most often they are reversible, but they may be persistent."),
    c("fluphenazine", "side-effects", ADVERSE, "Extrapyramidal reactions may be alarming, and the patient should be forewarned and reassured. These reactions can usually be controlled by administration of antiparkinsonian drugs such as benztropine mesylate or intravenous caffeine and sodium benzoate injection, and by subsequent reduction in dosage.", "These movement reactions may be alarming, and you should be warned about them in advance. They can usually be controlled with antiparkinsonian medicines such as benztropine, and by then lowering the dose."),
    c("fluphenazine", "urgent-help", ADVERSE, "Symptoms of dystonia, prolonged abnormal contractions of muscle groups, may occur in susceptible individuals during the first few days of treatment. Dystonic symptoms include: spasm of the neck muscles, sometimes progressing to tightness of the throat, swallowing difficulty, difficulty breathing, and/or protrusion of the tongue.", "Dystonia (long muscle spasms) may occur in susceptible people during the first few days of treatment. Symptoms include spasm of the neck muscles, sometimes progressing to tightness of the throat, trouble swallowing, trouble breathing and/or the tongue sticking out."),
    c("fluphenazine", "side-effects", PC, "Given the likelihood that some patients exposed chronically to neuroleptics will develop tardive dyskinesia, it is advised that all patients in whom chronic use is contemplated be given, if possible, full information about this risk.", "Because some people exposed over a long time to neuroleptics (antipsychotics) will develop tardive dyskinesia (abnormal movements that may be permanent), everyone for whom long-term use is planned should, if possible, be given full information about this risk."),

    /* ---- trifluoperazine tablets ---- */
    c("trifluoperazine", "used-for", IND, "For the management of schizophrenia.", "Trifluoperazine is used for the management of schizophrenia."),
    c("trifluoperazine", "used-for", IND, "Trifluoperazine hydrochloride tablets, USP are effective for the short-term treatment of generalized non-psychotic anxiety. However, trifluoperazine hydrochloride tablets are not the first drug to be used in therapy for most patients with non-psychotic anxiety because certain risks associated with its use are not shared by common alternative treatments (i.e., benzodiazepines).", "It is also effective for the short-term treatment of generalised anxiety that is not psychotic. But it is not the first medicine used for most people with this kind of anxiety, because some risks of using it are not shared by common alternatives (benzodiazepines)."),
    c("trifluoperazine", "precaution", IND, "When used in the treatment of non-psychotic anxiety, trifluoperazine hydrochloride tablets should not be administered at doses of more than 6 mg per day or for longer than 12 weeks because the use of trifluoperazine hydrochloride tablets at higher doses or for longer intervals may cause persistent tardive dyskinesia that may prove irreversible", "When used for non-psychotic anxiety, it should not be used at doses of more than 6 mg a day or for longer than 12 weeks, because higher doses or longer use may cause persistent tardive dyskinesia (abnormal movements) that may prove irreversible."),
    c("trifluoperazine", "precaution", BOX, "Elderly patients with dementia-related psychosis treated with antipsychotic drugs are at an increased risk of death.", "Elderly people with dementia-related psychosis who are treated with antipsychotic medicines are at an increased risk of death."),
    c("trifluoperazine", "contraindication", CONTRA, "A known hypersensitivity to phenothiazines, comatose or greatly depressed states due to central nervous system depressants and, in cases of existing blood dyscrasias, bone marrow depression and preexisting liver damage.", "It must not be used if you have a known hypersensitivity (allergy) to phenothiazines, in a coma or greatly depressed state caused by medicines or substances that slow the brain, or if you already have blood disorders, bone marrow depression or liver damage."),
    c("trifluoperazine", "how-to-take", DOSE, "Dosage should be adjusted to the needs of the individual. The lowest effective dosage should always be used. Dosage should be increased more gradually in debilitated or emaciated patients. When maximum response is achieved, dosage may be reduced gradually to a maintenance level.", "Your dose should be adjusted to your needs, and the lowest effective dose should always be used. The dose should be increased more gradually in people who are debilitated or very thin. When the maximum response is reached, the dose may be reduced gradually to a maintenance level."),
    c("trifluoperazine", "how-to-take", DOSE, "In general, dosages in the lower range are sufficient for most elderly patients. Since they appear to be more susceptible to hypotension and neuromuscular reactions, such patients should be observed closely.", "Elderly people usually need doses in the lower range. They appear more susceptible to low blood pressure and muscle and nerve reactions, so they should be watched closely."),
    c("trifluoperazine", "precaution", DOSE, "Although there is little likelihood of contact dermatitis due to the drug, persons with known sensitivity to phenothiazine drugs should avoid direct contact.", "There is little chance of a skin reaction from touching the drug, but people with known sensitivity to phenothiazines should avoid direct contact with it."),
    c("trifluoperazine", "side-effects", ADVERSE, "Drowsiness, dizziness, skin reactions, rash, dry mouth, insomnia, amenorrhea, fatigue, muscular weakness, anorexia, lactation, blurred vision and neuromuscular (extrapyramidal) reactions.", "Listed side effects: drowsiness, dizziness, skin reactions, rash, dry mouth, insomnia, missed periods (amenorrhea), tiredness, muscle weakness, loss of appetite, breast milk production (lactation), blurred vision, and neuromuscular (extrapyramidal) reactions (movement problems)."),
    c("trifluoperazine", "side-effects", ADVERSE, "They may be characterized by motor restlessness, be of the dystonic type, or they may resemble parkinsonism.", "The neuromuscular (extrapyramidal) reactions may show as motor restlessness, as dystonia (muscle spasms), or they may resemble parkinsonism."),
    c("trifluoperazine", "monitoring", ADVERSE, "Depending on the severity of symptoms, dosage should be reduced or discontinued.", "Depending on how severe these symptoms are, the dose should be reduced or the medicine stopped."),
    c("trifluoperazine", "side-effects", ADVERSE, "Symptoms may include agitation or jitteriness and sometimes insomnia. These symptoms often disappear spontaneously.", "Motor restlessness may show as agitation or jitteriness and sometimes insomnia. These symptoms often disappear on their own."),

    /* ---- loxapine capsules ---- */
    c("loxapine", "used-for", IND, "Loxapine Capsules are indicated for the treatment of schizophrenia.", "Loxapine capsules are used to treat schizophrenia."),
    c("loxapine", "precaution", BOX, "Elderly patients with dementia-related psychosis treated with antipsychotic drugs are at an increased risk of death.", "Elderly people with dementia-related psychosis who are treated with antipsychotic medicines are at an increased risk of death. The label says loxapine is not approved for treating dementia-related psychosis."),
    c("loxapine", "contraindication", CONTRA, "Loxapine is contraindicated in comatose or severe drug-induced depressed states (alcohol, barbiturates, narcotics, etc.). Loxapine is contraindicated in individuals with known hypersensitivity to dibenzoxazepines.", "Loxapine must not be used in a coma or in a severely depressed state caused by medicines or substances such as alcohol, barbiturates or narcotics, or by people known to be hypersensitive (allergic) to dibenzoxazepines."),
    c("loxapine", "how-to-take", DOSE, "Loxapine Capsules, USP are administered, usually in divided doses, two to four times a day. Daily dosage (in terms of base equivalents) should be adjusted to the individual patient's needs as assessed by the severity of symptoms and previous history of response to antipsychotic drugs.", "Loxapine capsules are usually taken in divided doses, two to four times a day. The daily dose is adjusted to your needs, judged by how severe your symptoms are and how you responded to antipsychotic medicines before. Your prescriber decides it, not you."),
    c("loxapine", "how-to-take", DOSE, "For maintenance therapy, dosage should be reduced to the lowest level compatible with symptom control", "For long-term (maintenance) treatment, the dose should be reduced to the lowest level that still controls symptoms."),
    c("loxapine", "side-effects", ADVERSE, "Drowsiness, usually mild, may occur at the beginning of therapy or when dosage is increased. It usually subsides with continued loxapine therapy.", "Drowsiness, usually mild, may occur at the beginning of treatment or when the dose is increased. It usually fades with continued treatment."),
    c("loxapine", "side-effects", ADVERSE, "Neuromuscular (extrapyramidal) reactions during the administration of loxapine have been reported frequently, often during the first few days of treatment. In most patients, these reactions involved parkinsonian-like symptoms such as tremor, rigidity, excessive salivation, and masked facies. Akathisia (motor restlessness) also has been reported relatively frequently. These symptoms are usually not severe and can be controlled by reduction of loxapine dosage or by administration of antiparkinson drugs in usual dosage.", "Neuromuscular (extrapyramidal) reactions, which are movement problems, have been reported frequently, often during the first few days of treatment. In most people they were Parkinson-like symptoms such as tremor, stiffness (rigidity), too much saliva and a mask-like face. Akathisia (motor restlessness) has also been reported relatively often. These are usually not severe and can be controlled by lowering the dose or by antiparkinson medicines."),
    c("loxapine", "urgent-help", ADVERSE, "Symptoms of dystonia, prolonged abnormal contractions of muscle groups, may occur in susceptible individuals during the first few days of treatment. Dystonic symptoms include: spasm of the neck muscles, sometimes progressing to tightness of the throat, swallowing difficulty, difficulty breathing, and/or protrusion of the tongue.", "Dystonia (long muscle spasms) may occur in susceptible people during the first few days of treatment. Symptoms include spasm of the neck muscles, sometimes progressing to tightness of the throat, trouble swallowing, trouble breathing and/or the tongue sticking out."),
    c("loxapine", "side-effects", WARN, "Tardive dyskinesia, a syndrome consisting of potentially irreversible, involuntary, dyskinetic movements, may develop in patients treated with antipsychotic drugs.", "Tardive dyskinesia, a condition of potentially irreversible, involuntary movements, may develop in people treated with antipsychotic medicines."),
    c("loxapine", "side-effects", WARN, "Both the risk of developing the syndrome and the likelihood that it will become irreversible are believed to increase as the duration of treatment and the total cumulative dose of antipsychotic drugs administered to the patient increase.", "Both the risk of developing tardive dyskinesia and the chance that it becomes irreversible are believed to increase with the length of treatment and the total amount of antipsychotic taken."),
    c("loxapine", "side-effects", ADVERSE, "Neuroleptic malignant syndrome (NMS) has been reported", "Neuroleptic malignant syndrome (NMS, a rare, serious reaction to antipsychotics) has been reported."),

    /* ---- perphenazine tablets ---- */
    c("perphenazine", "used-for", IND, "Perphenazine is indicated for use in the treatment of schizophrenia and for the control of severe nausea and vomiting in adults.", "Perphenazine is used to treat schizophrenia and to control severe nausea and vomiting in adults."),
    c("perphenazine", "precaution", IND, "Perphenazine has not been shown effective for the management of behavioral complications in patients with mental retardation.", "It has not been shown to work for behavioural complications in people with intellectual disability (the label's term is mental retardation)."),
    c("perphenazine", "precaution", BOX, "Elderly patients with dementia-related psychosis treated with antipsychotic drugs are at an increased risk of death.", "Elderly people with dementia-related psychosis who are treated with antipsychotic medicines are at an increased risk of death. The label says perphenazine is not approved for treating dementia-related psychosis."),
    c("perphenazine", "contraindication", CONTRA, "Perphenazine products are contraindicated in comatose or greatly obtunded patients and in patients receiving large doses of central nervous system depressants (barbiturates, alcohol, narcotics, analgesics, or antihistamines); in the presence of existing blood dyscrasias, bone marrow depression, or liver damage; and in patients who have shown hypersensitivity to perphenazine products, their components, or related compounds.", "Perphenazine must not be used in a coma or when very dull (obtunded); if you are receiving large doses of medicines that slow the brain (barbiturates, alcohol, narcotics, painkillers or antihistamines); if you already have blood disorders, bone marrow depression or liver damage; or if you have shown hypersensitivity (allergy) to perphenazine, its ingredients or related compounds."),
    c("perphenazine", "contraindication", CONTRA, "Perphenazine products are also contraindicated in patients with suspected or established subcortical brain damage, with or without hypothalamic damage, since a hyperthermic reaction with temperatures in excess of 104°F may occur in such patients, sometimes not until 14 to 16 hours after drug administration.", "It must also not be used in people with suspected or established brain damage deep in the brain (subcortical brain damage), because a hyperthermic reaction (a very high fever, above 104°F) may occur, sometimes not until 14 to 16 hours after the dose."),
    c("perphenazine", "interactions", INTER, "The concomitant administration of other drugs that inhibit the activity of P450 2D6 may acutely increase plasma concentrations of antipsychotics. Among these are tricyclic antidepressants and selective serotonin reuptake inhibitors, e.g., fluoxetine, sertraline and paroxetine.", "Other medicines that block the body's P450 2D6 enzyme can quickly raise the blood levels of antipsychotics. These include tricyclic antidepressants and SSRI antidepressants such as fluoxetine, sertraline and paroxetine."),
    c("perphenazine", "how-to-take", DOSE, "Dosage must be individualized and adjusted according to the severity of the condition and the response obtained. As with all potent drugs, the best dose is the lowest dose that will produce the desired clinical effect.", "Your dose must be set for you and adjusted according to how severe your condition is and how you respond. As with all potent medicines, the best dose is the lowest dose that gives the desired effect."),
    c("perphenazine", "how-to-take", DOSE, "Since extrapyramidal symptoms increase in frequency and severity with increased dosage, it is important to employ the lowest effective dose. These symptoms have disappeared upon reduction of dosage, withdrawal of the drug, or administration of an antiparkinsonian agent.", "Extrapyramidal symptoms (movement problems) become more frequent and more severe as the dose goes up, so the lowest effective dose matters. These symptoms have disappeared when the dose was lowered, the medicine was stopped, or an antiparkinsonian medicine was given."),
    c("perphenazine", "side-effects", ADVERSE, "With the piperazine group (of which perphenazine is an example), the extrapyramidal symptoms are more common, and others (e.g., sedative effects, jaundice, and blood dyscrasias) are less frequently seen.", "With this group of phenothiazines (which includes perphenazine), extrapyramidal symptoms (movement problems) are more common, and sedation, jaundice and blood disorders are seen less often."),
    c("perphenazine", "side-effects", ADVERSE, "Extrapyramidal symptoms can usually be controlled by the concomitant use of effective antiparkinsonian drugs, such as benztropine mesylate, and/or by reduction in dosage. In some instances, however, these extrapyramidal reactions may persist after discontinuation of treatment with perphenazine.", "These movement problems can usually be controlled with antiparkinsonian medicines such as benztropine and/or by lowering the dose. In some cases, however, they may persist after perphenazine is stopped."),
    c("perphenazine", "urgent-help", ADVERSE, "Symptoms of dystonia, prolonged abnormal contractions of muscle groups, may occur in susceptible individuals during the first few days of treatment. Dystonic symptoms include: spasm of the neck muscles, sometimes progressing to tightness of the throat, swallowing difficulty, difficulty breathing, and/or protrusion of the tongue.", "Dystonia (long muscle spasms) may occur in susceptible people during the first few days of treatment. Symptoms include spasm of the neck muscles, sometimes progressing to tightness of the throat, trouble swallowing, trouble breathing and/or the tongue sticking out."),
    c("perphenazine", "side-effects", WARN, "Tardive dyskinesia, a syndrome consisting of potentially irreversible, involuntary, dyskinetic movements, may develop in patients treated with antipsychotic drugs. Older patients are at increased risk for development of tardive dyskinesia.", "Tardive dyskinesia, a condition of potentially irreversible, involuntary movements, may develop in people treated with antipsychotic medicines. Older people are at increased risk."),
    c("perphenazine", "side-effects", PC, "Given the likelihood that a substantial proportion of patients exposed chronically to antipsychotics will develop tardive dyskinesia, it is advised that all patients in whom chronic use is contemplated be given, if possible, full information about this risk.", "Because a substantial proportion of people exposed to antipsychotics over a long time will develop tardive dyskinesia, everyone for whom long-term use is planned should, if possible, be given full information about this risk."),

    /* ---- thioridazine tablets ---- */
    c("thioridazine", "precaution", BOX, "Thioridazine has been shown to prolong the QTc interval in a dose related manner, and drugs with this potential, including thioridazine, have been associated with Torsades de pointes type arrhythmias and sudden death.", "Thioridazine lengthens the QTc interval (a heart rhythm measurement) according to the dose, and medicines that do this, including thioridazine, have been linked to Torsades de pointes-type arrhythmias (dangerous irregular heart rhythms) and sudden death."),
    c("thioridazine", "used-for", IND, "Thioridazine hydrochloride tablets are indicated for the management of schizophrenic patients who fail to respond adequately to treatment with other antipsychotic drugs.", "Thioridazine is used to manage schizophrenia in people who do not respond adequately to treatment with other antipsychotic medicines."),
    c("thioridazine", "precaution", IND, "before initiating treatment with thioridazine hydrochloride tablets, it is strongly recommended that a patient be given at least two trials, each with a different antipsychotic drug product, at an adequate dose, and for an adequate duration", "Because of the heart risks, it is strongly recommended that you first have at least two trials of different antipsychotic medicines, each at an adequate dose and for an adequate time, before thioridazine is started."),
    c("thioridazine", "contraindication", CONTRA, "Thioridazine hydrochloride tablet use should be avoided in combination with other drugs that are known to prolong the QTc interval and in patients with congenital long QT syndrome or a history of cardiac arrhythmias.", "Thioridazine should be avoided together with other medicines known to lengthen the QTc interval, and in people with congenital long QT syndrome (a heart rhythm condition present from birth) or a history of cardiac arrhythmias (irregular heartbeats)."),
    c("thioridazine", "interactions", INTER, "Reduced cytochrome P450 2D6 isozyme activity, drugs which inhibit this isozyme (e.g., fluoxetine and paroxetine), and certain other drugs (e.g., fluvoxamine, propranolol, and pindolol) appear to appreciably inhibit the metabolism of thioridazine. The resulting elevated levels of thioridazine would be expected to augment the prolongation of the QTc interval associated with thioridazine and may increase the risk of serious, potentially fatal, cardiac arrhythmias, such as Torsades de pointes type arrhythmias.", "Medicines that block the body's P450 2D6 enzyme (for example fluoxetine and paroxetine) and certain other medicines (for example fluvoxamine, propranolol and pindolol) appear to greatly slow how fast thioridazine is broken down. The higher thioridazine levels would be expected to lengthen the QTc interval further and may raise the risk of serious, potentially fatal, irregular heart rhythms such as Torsades de pointes."),
    c("thioridazine", "contraindication", INTER, "Therefore, thioridazine is contraindicated with these drugs as well as in patients, comprising about 7% of the normal population, who are known to have a genetic defect leading to reduced levels of activity of P450 2D6", "Because of this, thioridazine must not be used with those medicines, nor in people (about 7% of the population) who are known to have a genetic defect that reduces the activity of the P450 2D6 enzyme."),
    c("thioridazine", "urgent-help", PC, "Patients should be informed that thioridazine has been associated with potentially fatal heart rhythm disturbances. The risk of such events may be increased when certain drugs are given together with thioridazine. Therefore, patients should inform the prescriber that they are receiving thioridazine treatment before taking any new medication.", "Thioridazine has been linked to potentially fatal heart rhythm disturbances, and the risk may be higher when certain medicines are taken with it. Tell the prescriber that you take thioridazine before you start any new medicine."),
    c("thioridazine", "how-to-take", DOSE, "Dosage must be individualized and the smallest effective dosage should be determined for each patient", "Your dose must be set for you, and the smallest effective dose should be found for you."),
    c("thioridazine", "side-effects", ADVERSE, "In the recommended dosage ranges with thioridazine hydrochloride most side effects are mild and transient.", "At the recommended doses, most side effects are mild and temporary."),
    c("thioridazine", "side-effects", ADVERSE, "Drowsiness may be encountered on occasion, especially where large doses are given early in treatment. Generally, this effect tends to subside with continued therapy or a reduction in dosage.", "Drowsiness may occur on occasion, especially when large doses are given early in treatment. It generally eases with continued treatment or a lower dose."),
    c("thioridazine", "side-effects", ADVERSE, "Dryness of mouth, blurred vision, constipation, nausea, vomiting, diarrhea, nasal stuffiness, and pallor have been seen.", "Dry mouth, blurred vision, constipation, nausea, vomiting, diarrhoea, a stuffy nose and paleness have been seen."),
    c("thioridazine", "side-effects", ADVERSE, "Galactorrhea, breast engorgement, amenorrhea, inhibition of ejaculation, and peripheral edema have been described.", "Breast milk production (galactorrhea), swollen breasts, missed periods (amenorrhea), difficulty ejaculating and swelling of the legs and feet (peripheral edema) have been described."),
    c("thioridazine", "urgent-help", ADVERSE, "Thioridazine produces a dose related prolongation of the QTc interval, which is associated with the ability to cause Torsades de pointes type arrhythmias, a potentially fatal polymorphic ventricular tachycardia, and sudden death", "Thioridazine lengthens the QTc interval according to the dose, which is linked to the ability to cause Torsades de pointes-type arrhythmias (a potentially fatal fast irregular heart rhythm) and sudden death."),

    /* ---- thiothixene capsules ---- */
    c("thiothixene", "used-for", IND, "Thiothixene capsules are effective in the management of schizophrenia.", "Thiothixene capsules are used in the management of schizophrenia."),
    c("thiothixene", "precaution", BOX, "Elderly patients with dementia-related psychosis treated with antipsychotic drugs are at an increased risk of death.", "Elderly people with dementia-related psychosis who are treated with antipsychotic medicines are at an increased risk of death. The label says thiothixene is not approved for treating dementia-related psychosis."),
    c("thiothixene", "contraindication", CONTRA, "Thiothixene capsules are contraindicated in patients with circulatory collapse, comatose states, central nervous system depression due to any cause, and blood dyscrasias. Thiothixene capsules are contraindicated in individuals who have shown hypersensitivity to the drug. It is not known whether there is a cross sensitivity between the thioxanthenes and the phenothiazine derivatives, but this possibility should be considered.", "Thiothixene must not be used in circulatory collapse, in a coma, in central nervous system depression (a dangerous slowing of brain function) from any cause, or with blood disorders (blood dyscrasias). It must not be used by people who have shown hypersensitivity (allergy) to it. It is not known whether people allergic to thioxanthenes (the group it belongs to) are also allergic to phenothiazines, but this possibility should be considered."),
    c("thiothixene", "interactions", INTER, "Hepatic microsomal enzyme inducing agents, such as carbamazepine, were found to significantly increase the clearance of thiothixene. Patients receiving these drugs should be observed for signs of reduced thiothixene effectiveness", "Medicines that speed up the liver's enzymes, such as carbamazepine, were found to clear thiothixene from the body much faster. People taking them should be watched for signs that thiothixene is working less well."),
    c("thiothixene", "interactions", INTER, "Due to a possible additive effect with hypotensive agents, patients receiving these drugs should be observed closely for signs of excessive hypotension when thiothixene is added to their drug regimen", "Thiothixene may add to the effect of blood pressure-lowering medicines, so people taking those should be watched closely for signs of too low blood pressure when thiothixene is added."),
    c("thiothixene", "how-to-take", DOSE, "Dosage of thiothixene capsules should be individually adjusted depending on the chronicity and severity of the symptoms of schizophrenia. In general, small doses should be used initially and gradually increased to the optimal effective level, based on patient response.", "Your dose is adjusted for you, depending on how long you have had schizophrenia symptoms and how severe they are. In general, small doses are used at first and gradually increased to the best effective level, based on how you respond. Your prescriber decides it, not you."),
    c("thiothixene", "precaution", DOSE, "The use of thiothixene capsules in children under 12 years of age is not recommended because safe conditions for its use have not been established.", "It is not recommended for children under 12 years of age, because safe conditions for its use have not been established."),
    c("thiothixene", "side-effects", ADVERSE, "Tachycardia, hypotension, lightheadedness, and syncope.", "Heart and blood pressure effects listed: a fast heartbeat (tachycardia), low blood pressure (hypotension), lightheadedness and fainting (syncope)."),
    c("thiothixene", "side-effects", ADVERSE, "Drowsiness, usually mild, may occur although it usually subsides with continuation of thiothixene therapy.", "Drowsiness, usually mild, may occur, although it usually fades as treatment continues."),
    c("thiothixene", "side-effects", ADVERSE, "Restlessness, agitation and insomnia have been noted with thiothixene. Seizures and paradoxical exacerbation of psychotic symptoms have occurred with thiothixene infrequently.", "Restlessness, agitation and insomnia have been noted. Seizures, and a worsening of psychotic symptoms instead of an improvement, have occurred infrequently."),
    c("thiothixene", "side-effects", WARN, "Tardive dyskinesia, a syndrome consisting of potentially irreversible, involuntary, dyskinetic movements may develop in patients treated with antipsychotic drugs, including thiothixene", "Tardive dyskinesia, a condition of potentially irreversible, involuntary movements, may develop in people treated with antipsychotic medicines, including thiothixene."),
    c("thiothixene", "side-effects", PC, "Given the likelihood that some patients exposed chronically to antipsychotics will develop tardive dyskinesia, it is advised that all patients in whom chronic use is contemplated be given, if possible, full information about this risk.", "Because some people exposed to antipsychotics over a long time will develop tardive dyskinesia, everyone for whom long-term use is planned should, if possible, be given full information about this risk."),

    /* ---- pimozide tablets ---- */
    c("pimozide", "used-for", IND, "Pimozide tablets, USP are indicated for the suppression of motor and phonic tics in patients with Tourette’s Disorder who have failed to respond satisfactorily to standard treatment. Pimozide tablets, USP are not intended as a treatment of first choice nor is it intended for the treatment of tics that are merely annoying or cosmetically troublesome.", "Pimozide is used to suppress motor tics (movements) and phonic tics (sounds) in people with Tourette's disorder who have not responded satisfactorily to standard treatment. It is not meant as a first-choice treatment, nor for tics that are merely annoying or cosmetically troublesome."),
    c("pimozide", "contraindication", CONTRA, "Pimozide is contraindicated in the treatment of simple tics or tics other than those associated with Tourette’s Disorder. 2. Pimozide should not be used in patients taking drugs that may, themselves, cause motor and phonic tics (e.g., pemoline, methylphenidate and amphetamines) until such patients have been withdrawn from these drugs to determine whether or not the drugs, rather than Tourette’s Disorder, are responsible for the tics.", "Pimozide must not be used for simple tics, or for tics other than those associated with Tourette's disorder. It should not be used in people taking medicines that can themselves cause motor and phonic tics (for example pemoline, methylphenidate and amphetamines) until they have been withdrawn from those medicines, to find out whether the medicines rather than Tourette's disorder are causing the tics."),
    c("pimozide", "contraindication", CONTRA, "3. Because pimozide prolongs the QT interval of the electrocardiogram it is contraindicated in patients with congenital long QT syndrome, patients with a history of cardiac arrhythmias, patients taking other drugs which prolong the QT interval of the electrocardiogram or patients with known hypokalemia or hypomagnesemia", "Because pimozide lengthens the QT interval (a heart rhythm measurement on the ECG), it must not be used in people with congenital long QT syndrome (a heart rhythm condition present from birth), a history of cardiac arrhythmias (irregular heartbeats), people taking other medicines that lengthen the QT interval, or people with known low potassium (hypokalemia) or low magnesium (hypomagnesemia) levels."),
    c("pimozide", "contraindication", CONTRA, "4. Pimozide is contraindicated in patients with severe toxic central nervous system depression or comatose states from any cause.", "Pimozide must not be used in severe toxic central nervous system depression (a dangerous slowing of brain function) or in a coma from any cause."),
    c("pimozide", "interactions", INTER, "Because pimozide prolongs the QT interval of the electrocardiogram, an additive effect on QT interval would be anticipated if administered with other drugs, such as phenothiazines, tricyclic antidepressants or antiarrhythmic agents, which prolong the QT interval. Accordingly, pimozide should not be given with dofetilide, sotalol, quinidine, other Class Ia and III anti-arrhythmics, mesoridazine, thioridazine, chlorpromazine, droperidol, sparfloxacin, gatifloxacin, moxifloxacin, halofantrine, mefloquine, pentamidine, arsenic trioxide, levomethadyl acetate, dolasetron mesylate, probucol, tacrolimus, ziprasidone, or other drugs that have demonstrated QT prolongation as one of their pharmacodynamic effects.", "Because pimozide lengthens the QT interval, the effect would be expected to add up with other medicines that do the same, such as phenothiazines, tricyclic antidepressants or medicines for irregular heartbeats. So pimozide should not be given with dofetilide, sotalol, quinidine, other Class Ia and III antiarrhythmics, mesoridazine, thioridazine, chlorpromazine, droperidol, sparfloxacin, gatifloxacin, moxifloxacin, halofantrine, mefloquine, pentamidine, arsenic trioxide, levomethadyl acetate, dolasetron mesylate, probucol, tacrolimus, ziprasidone, or other medicines shown to lengthen the QT interval."),
    c("pimozide", "how-to-take", DOSE, "The suppression of tics by pimozide tablets, USP requires a slow and gradual introduction of the drug. The patient’s dose should be carefully adjusted to a point where the suppression of tics and the relief afforded is balanced against the untoward side effects of the drug.", "Suppressing tics with pimozide needs a slow and gradual start. Your dose should be carefully adjusted to a point where the tic relief is balanced against the unwanted side effects."),
    c("pimozide", "monitoring", DOSE, "An ECG should be done at baseline and periodically thereafter, especially during the period of dose adjustment", "An ECG (heart tracing) should be done before starting and from time to time afterwards, especially while the dose is being adjusted."),
    c("pimozide", "how-to-take", DOSE, "Periodic attempts should be made to reduce the dosage of pimozide tablets, USP to see whether or not tics persist at the level and extent first identified.", "From time to time, attempts should be made to reduce the dose, to see whether the tics persist at the level first seen."),
    c("pimozide", "precaution", PC, "Treatment with pimozide tablets, exposes the patient to serious risks. A decision to use pimozide tablets, chronically in Tourette’s Disorder is one that deserves full consideration by the patient (or patient’s family) as well as by the treating physician.", "Treatment with pimozide exposes you to serious risks. A decision to use it over a long time for Tourette's disorder deserves full consideration by you (or your family) as well as by your doctor."),
    c("pimozide", "side-effects", ADVERSE, "Neuromuscular (extrapyramidal) reactions during the administration of pimozide have been reported frequently, often during the first few days of treatment. In most patients, these reactions involved Parkinson-like symptoms which, when first observed, were usually mild to moderately severe and usually reversible.", "Neuromuscular (extrapyramidal) reactions, which are movement problems, have been reported frequently, often during the first few days of treatment. In most people they were Parkinson-like symptoms, usually mild to moderately severe and usually reversible."),
    c("pimozide", "side-effects", ADVERSE, "Generally the occurrence and severity of most extrapyramidal symptoms are dose-related since they occur at relatively high doses and have been shown to disappear or become less severe when the dose is reduced. Administration of antiparkinson drugs such as benztropine mesylate or trihexyphenidyl hydrochloride may be required for control of such reactions.", "Most of these movement problems depend on the dose: they occur at relatively high doses and have disappeared or become less severe when the dose was reduced. Antiparkinson medicines such as benztropine or trihexyphenidyl may be needed to control them."),
    c("pimozide", "side-effects", WARN, "A syndrome consisting of potentially irreversible, involuntary, dyskinetic movements may develop in patients treated with antipsychotic drugs.", "Tardive dyskinesia, a condition of potentially irreversible, involuntary movements, may develop in people treated with antipsychotic medicines."),

    /* ---- molindone tablets ---- */
    c("molindone", "used-for", IND, "Molindone Hydrochloride Tablets, USP are indicated for the management of schizophrenia.", "Molindone is used in the management of schizophrenia."),
    c("molindone", "precaution", BOX, "Elderly patients with dementia-related psychosis treated with antipsychotic drugs are at an increased risk of death.", "Elderly people with dementia-related psychosis who are treated with antipsychotic medicines are at an increased risk of death. The label says molindone is not approved for treating dementia-related psychosis."),
    c("molindone", "contraindication", CONTRA, "Molindone Hydrochloride Tablets are contraindicated in severe central nervous system depression (alcohol, barbiturates, narcotics, etc.) or comatose states, and in patients with known hypersensitivity to the drug.", "Molindone must not be used in severe central nervous system depression (a dangerous slowing of brain function, for example from alcohol, barbiturates or narcotics) or in a coma, or by people known to be hypersensitive (allergic) to it."),
    c("molindone", "interactions", INTER, "Potentiation of drugs administered concurrently with Molindone Hydrochloride has not been reported. Additionally, animal studies have not shown increased toxicity when Molindone Hydrochloride is given concurrently with representative members of three classes of drugs (i.e., barbiturates, chloral hydrate and antiparkinson drugs).", "The label says that a stronger effect of other medicines taken at the same time as molindone has not been reported, and animal studies did not show more toxicity when it was given with barbiturates, chloral hydrate or antiparkinson drugs. This is not a list of medicines that are safe to combine with it.", ["US prescribing information, which is written for clinicians: this restates it in plain words.", "Not being named, or not being reported, does not make a combination safe. Ask your pharmacist.", "US label only: Indian approval, strengths and warnings may differ."]),
    c("molindone", "how-to-take", DOSE, "Initial and maintenance doses of Molindone Hydrochloride Tablets should be individualized.", "Your starting dose and your long-term (maintenance) dose should be set for you."),
    c("molindone", "how-to-take", DOSE, "Elderly and debilitated patients should be started on lower dosage.", "Elderly and debilitated people should be started on a lower dose."),
    c("molindone", "side-effects", ADVERSE, "The most frequently occurring effect is initial drowsiness that generally subsides with continued usage of the drug or lowering of the dose. Noted less frequently were depression, hyperactivity and euphoria.", "The most frequent effect is drowsiness at first, which generally eases with continued use or a lower dose. Depression, hyperactivity and euphoria were noted less often."),
    c("molindone", "side-effects", ADVERSE, "Extrapyramidal symptoms noted below may occur in susceptible individuals and are usually reversible with appropriate management. Akathisia Motor restlessness may occur early.", "Extrapyramidal symptoms (movement problems) may occur in susceptible people and are usually reversible with appropriate management. Akathisia (motor restlessness) may occur early."),
    c("molindone", "side-effects", ADVERSE, "Akinesia, characterized by rigidity, immobility and reduction of voluntary movements and tremor, have been observed. Occurrence is less frequent than akathisia.", "Akinesia (rigidity, immobility and fewer voluntary movements) and tremor have been observed, less often than akathisia."),
    c("molindone", "urgent-help", ADVERSE, "Symptoms of dystonia, prolonged abnormal contractions of muscle groups, may occur in susceptible individuals during the first few days of treatment. Dystonic symptoms include: spasm of the neck muscles, sometimes progressing to tightness of the throat, swallowing difficulty, difficulty breathing, and/or protrusion of the tongue.", "Dystonia (long muscle spasms) may occur in susceptible people during the first few days of treatment. Symptoms include spasm of the neck muscles, sometimes progressing to tightness of the throat, trouble swallowing, trouble breathing and/or the tongue sticking out."),
    c("molindone", "side-effects", WARN, "Tardive dyskinesia, a syndrome consisting of potentially irreversible, involuntary, dyskinetic movements may develop in patients treated with antipsychotic drugs.", "Tardive dyskinesia, a condition of potentially irreversible, involuntary movements, may develop in people treated with antipsychotic medicines."),

    /* ---- asenapine sublingual tablets ---- */
    c("asenapine", "used-for", IND, "Asenapine sublingual tablets are an atypical antipsychotic indicated for (1): Schizophrenia in adults Bipolar I disorder Acute monotherapy treatment of manic or mixed episodes, in adults and pediatric patients 10 to 17 years of age Adjunctive treatment to lithium or valproate in adults Maintenance monotherapy treatment in adults", "Asenapine (taken as a tablet under the tongue) is an atypical antipsychotic. The US label lists: schizophrenia in adults; bipolar I disorder (acute treatment of manic or mixed episodes on its own in adults and in young people aged 10 to 17 years; as an add-on to lithium or valproate in adults; and long-term treatment on its own in adults)."),
    c("asenapine", "precaution", BOX, "Elderly patients with dementia-related psychosis treated with antipsychotic drugs are at an increased risk of death.", "Elderly people with dementia-related psychosis who are treated with antipsychotic medicines are at an increased risk of death. The label says asenapine is not approved for treating dementia-related psychosis."),
    c("asenapine", "contraindication", CONTRA, "Severe hepatic impairment (Child-Pugh C)", "Asenapine must not be used if you have severe hepatic (liver) impairment (Child-Pugh C)."),
    c("asenapine", "contraindication", CONTRA, "A history of hypersensitivity reactions to asenapine. Reactions have included anaphylaxis, angioedema, hypotension, tachycardia, swollen tongue, dyspnea, wheezing and rash", "Asenapine must not be used if you have ever had a hypersensitivity (allergic) reaction to it. Reactions have included anaphylaxis (a severe allergic reaction), angioedema (swelling), low blood pressure, a fast heartbeat, a swollen tongue, shortness of breath, wheezing and rash."),
    c("asenapine", "how-to-take", PC, "Counsel patients on proper sublingual administration of asenapine sublingual tablets and advise them to read the FDA-approved patient labeling (Instructions for Use).", "You should be shown how to take the tablets properly under the tongue (sublingually) and should read the written patient instructions that come with them.", ["US prescribing information, which is written for clinicians: this restates it in plain words.", "The label refers to US patient instructions; ask for the instructions that come with the product you are given.", "US label only: Indian approval, strengths and warnings may differ."]),
    c("asenapine", "urgent-help", PC, "Counsel patients on the signs and symptoms of a serious allergic reaction (e.g., difficulty breathing, itching, swelling of the face, tongue or throat, feeling lightheaded etc.) and to seek immediate emergency assistance if they develop any of these signs and symptoms", "Signs of a serious allergic reaction include difficulty breathing, itching, swelling of the face, tongue or throat, and feeling lightheaded. Seek immediate emergency assistance if you get any of these."),
    c("asenapine", "side-effects", PC, "Inform patients that application site reactions, primarily in the sublingual area, including oral ulcers, blisters, peeling/sloughing and inflammation have been reported. Instruct patients to monitor for these reactions", "Reactions where the tablet sits, mainly under the tongue, have been reported: mouth ulcers, blisters, peeling and inflammation. You should watch for these."),
    c("asenapine", "side-effects", PC, "Inform patients that numbness or tingling of the mouth or throat may occur directly after administration of asenapine sublingual tablets and usually resolves within 1 hour", "Numbness or tingling of the mouth or throat may occur right after taking the tablet and usually goes away within 1 hour."),
    c("asenapine", "urgent-help", PC, "Patients should contact their health care provider or report to the emergency room if they experience the following signs and symptoms of NMS, including hyperpyrexia, muscle rigidity, altered mental status, and evidence of autonomic instability (irregular pulse or blood pressure, tachycardia, diaphoresis, and cardiac dysrhythmia)", "Contact your healthcare provider or go to the emergency room if you have signs of neuroleptic malignant syndrome (NMS, a rare, serious reaction to antipsychotics): a very high fever, muscle stiffness, altered mental state, an irregular pulse or blood pressure, a fast heartbeat, sweating or an irregular heart rhythm."),
    c("asenapine", "side-effects", PC, "Counsel patients on the signs and symptoms of tardive dyskinesia and to contact their health care provider if these abnormal movements occur", "Tardive dyskinesia is a problem of abnormal movements that can be linked to antipsychotic medicines. Contact your healthcare provider if you notice abnormal movements."),
    c("asenapine", "side-effects", PC, "Educate patients about the risk of metabolic changes, how to recognize symptoms of hyperglycemia (high blood sugar) and diabetes mellitus, and the need for specific monitoring, including blood glucose, lipids, and weight", "Asenapine can cause metabolic changes. Your healthcare provider should explain how to recognise the symptoms of high blood sugar (hyperglycemia) and diabetes, and why your blood sugar, blood fats (lipids) and weight need to be monitored."),
    c("asenapine", "precaution", PC, "Educate patients about the risk of orthostatic hypotension (symptoms include feeling dizzy or lightheaded upon standing) especially early in treatment, and also at times of re-initiating treatment or increases in dose", "It can cause orthostatic hypotension (low blood pressure when you stand up; you may feel dizzy or lightheaded), especially early in treatment, and when treatment is restarted or the dose is increased."),
    c("asenapine", "monitoring", PC, "Advise patients with a pre-existing low WBC or a history of drug induced leukopenia/neutropenia they should have their CBC monitored while taking sublingual tablets", "If you already have a low white blood cell count, or have had a drop in white cells caused by a medicine (leukopenia or neutropenia), you should have your blood count (CBC) monitored while taking these tablets."),
    c("asenapine", "precaution", PC, "Caution patients about performing activities requiring mental alertness, such as operating hazardous machinery or operating a motor vehicle, until they are reasonably certain that asenapine sublingual tablets therapy does not affect them adversely", "Do not do activities that need you to be mentally alert, such as operating hazardous machinery or driving, until you are reasonably certain that asenapine does not affect you badly."),
    c("asenapine", "precaution", PC, "Counsel patients regarding appropriate care in avoiding overheating and dehydration", "Take care to avoid overheating and dehydration."),
    c("asenapine", "interactions", PC, "Advise patients to inform their health care provider if they are taking, or plan to take, any prescription or over-the-counter medications since there is a potential for interactions", "Tell your healthcare provider about any prescription or over-the-counter medicine you are taking or plan to take, because interactions are possible."),
    c("asenapine", "precaution", PC, "Advise patients that asenapine sublingual tablets may cause fetal harm as well as extrapyramidal and/or withdrawal symptoms in a neonate. Advise patients to notify their healthcare provider with a known or suspected pregnancy", "Asenapine may harm an unborn baby, and may cause extrapyramidal symptoms (movement problems) and/or withdrawal symptoms in a newborn. Tell your healthcare provider if you know or suspect you are pregnant."),
    c("asenapine", "precaution", PC, "Phenylketonurics: Contains Phenylalanine 0.17 mg per tablet. Phenylalanine can be harmful to patients with phenylketonuria (PKU).", "The tablets contain phenylalanine (0.17 mg per tablet), which can be harmful to people with phenylketonuria (PKU, a condition in which the body cannot process phenylalanine)."),
    c("asenapine", "side-effects", ADVERSE, "The most common adverse reactions (≥5% and at least twice the rate of placebo) reported with acute treatment in adults with schizophrenia were akathisia, oral hypoesthesia, and somnolence.", "In adults with schizophrenia, the most common side effects (5% or more of people and at least twice as often as with a dummy tablet) were akathisia (inner restlessness), oral hypoesthesia (numbness in the mouth) and somnolence (sleepiness)."),

    /* ---- paliperidone extended-release tablets ---- */
    c("paliperidone", "used-for", IND, "Paliperidone is an atypical antipsychotic agent indicated for Treatment of schizophrenia", "Paliperidone is an atypical antipsychotic used to treat schizophrenia."),
    c("paliperidone", "used-for", IND, "Treatment of schizoaffective disorder as monotherapy and as an adjunct to mood stabilizers and/or antidepressants.", "It is also used to treat schizoaffective disorder, on its own or as an add-on to mood stabilisers and/or antidepressants."),
    c("paliperidone", "precaution", BOX, "Elderly patients with dementia-related psychosis treated with antipsychotic drugs are at an increased risk of death.", "Elderly people with dementia-related psychosis who are treated with antipsychotic medicines are at an increased risk of death. The label says paliperidone is not approved for treating dementia-related psychosis."),
    c("paliperidone", "contraindication", CONTRA, "Paliperidone is contraindicated in patients with a known hypersensitivity to either paliperidone or risperidone, or to any of the excipients in the Paliperidone formulation.", "Do not take it if you are known to be allergic (hypersensitive) to paliperidone, to risperidone, or to any other ingredient in the tablets."),
    c("paliperidone", "how-to-take", PC, "Patients should be informed that paliperidone should be swallowed whole with the aid of liquids. Tablets should not be chewed, divided, or crushed.", "Swallow paliperidone tablets whole with a drink. Do not chew, divide or crush them."),
    c("paliperidone", "urgent-help", PC, "Counsel patients about a potentially fatal adverse reaction, Neuroleptic Malignant Syndrome (NMS), that has been reported in association with administration of antipsychotic drugs. Advise patients, family members, or caregivers to contact their healthcare provider or report to the emergency room if they experience signs and symptoms of NMS, including hyperpyrexia, muscle rigidity, altered mental status including delirium, and evidence of autonomic instability (irregular pulse or blood pressure, tachycardia, diaphoresis, and cardiac dysrhythmia)", "Antipsychotic medicines have been linked to a potentially fatal reaction called neuroleptic malignant syndrome (NMS). Contact your healthcare provider or go to the emergency room if you or a family member have a very high fever, muscle stiffness, confusion or delirium, an irregular pulse or blood pressure, a fast heartbeat, sweating or an irregular heart rhythm."),
    c("paliperidone", "side-effects", PC, "Counsel patients on the signs and symptoms of tardive dyskinesia and to contact their healthcare provider if these abnormal movements occur", "Tardive dyskinesia is a problem of abnormal movements that can be linked to antipsychotic medicines. Contact your healthcare provider if you notice abnormal movements."),
    c("paliperidone", "side-effects", PC, "Educate patients about the risk of metabolic changes, how to recognize symptoms of hyperglycemia and diabetes mellitus, and the need for specific monitoring, including blood glucose, lipids, and weight", "Paliperidone can cause metabolic changes. Your healthcare provider should explain how to recognise the symptoms of high blood sugar (hyperglycemia) and diabetes, and why your blood sugar, blood fats (lipids) and weight need to be monitored."),
    c("paliperidone", "precaution", PC, "Educate patients about the risk of orthostatic hypotension and syncope, particularly at the time of initiating treatment, re-initiating treatment, or increasing the dose", "It can cause low blood pressure when you stand up (orthostatic hypotension) and fainting (syncope), particularly when treatment is started or restarted, or when the dose is increased."),
    c("paliperidone", "side-effects", PC, "Counsel patients on signs and symptoms of hyperprolactinemia that may be associated with chronic use of paliperidone. Advise them to seek medical attention if they experience any of the following: amenorrhea or galactorrhea in females, erectile dysfunction or gynecomastia in males", "Long-term use may raise the hormone prolactin (hyperprolactinemia). Seek medical attention if a woman has missed periods (amenorrhea) or breast milk production (galactorrhea), or if a man has erectile dysfunction or breast enlargement (gynecomastia)."),
    c("paliperidone", "precaution", PC, "Caution patients about performing activities requiring mental alertness, such as operating hazardous machinery, or operating a motor vehicle, until they are reasonably certain that paliperidone therapy does not affect them adversely", "Do not do activities that need you to be mentally alert, such as operating hazardous machinery or driving, until you are reasonably certain that paliperidone does not affect you badly."),
    c("paliperidone", "urgent-help", PC, "Advise patients of the possibility of painful or prolonged penile erections (priapism). Instruct the patient to seek immediate medical attention in the event of priapism", "A painful or prolonged erection (priapism) is possible. Seek immediate medical attention if it happens."),
    c("paliperidone", "precaution", PC, "Counsel patients on the importance of avoiding overheating and dehydration", "It is important to avoid overheating and dehydration."),
    c("paliperidone", "interactions", PC, "Advise patients to inform their healthcare providers if they are taking, or plan to take, any prescription or over-the-counter drugs, as there is a potential for interactions", "Tell your healthcare provider about any prescription or over-the-counter medicine you are taking or plan to take, because interactions are possible."),
    c("paliperidone", "precaution", PC, "Advise patients to avoid alcohol while taking paliperidone", "Avoid alcohol while taking paliperidone."),
    c("paliperidone", "precaution", PC, "Advise patients to notify their healthcare provider if they become pregnant or intend to become pregnant during treatment with paliperidone. Advise patients that paliperidone may cause extrapyramidal and/or withdrawal symptoms in a neonate.", "Tell your healthcare provider if you become pregnant or intend to become pregnant during treatment. Paliperidone may cause extrapyramidal symptoms (movement problems) and/or withdrawal symptoms in a newborn baby."),
    c("paliperidone", "precaution", PC, "Advise breastfeeding women using paliperidone to monitor infants for somnolence, failure to thrive, jitteriness, and extrapyramidal symptoms (tremors and abnormal muscle movements) and to seek medical care if they notice these signs", "If you are breastfeeding while using paliperidone, watch your baby for unusual sleepiness, poor growth or feeding (failure to thrive), jitteriness, and tremors or abnormal muscle movements, and seek medical care if you notice these signs."),

    /* ---- iloperidone tablets ---- */
    c("iloperidone", "used-for", IND, "FANAPT is an atypical antipsychotic indicated for: Treatment of schizophrenia in adults.", "Iloperidone is an atypical antipsychotic used to treat schizophrenia in adults."),
    c("iloperidone", "used-for", IND, "Acute treatment of manic or mixed episodes associated with bipolar I disorder in adults.", "It is also used for the acute treatment of manic or mixed episodes of bipolar I disorder in adults."),
    c("iloperidone", "precaution", BOX, "Elderly patients with dementia-related psychosis treated with antipsychotic drugs are at an increased risk of death.", "Elderly people with dementia-related psychosis who are treated with antipsychotic medicines are at an increased risk of death. The label says iloperidone is not approved for treating dementia-related psychosis."),
    c("iloperidone", "contraindication", CONTRA, "FANAPT is contraindicated in individuals with a known hypersensitivity reaction to the product. Anaphylaxis, angioedema, and other hypersensitivity reactions have been reported", "Iloperidone must not be used by people known to have had a hypersensitivity (allergic) reaction to it. Anaphylaxis (a severe allergic reaction), angioedema (swelling) and other allergic reactions have been reported."),
    c("iloperidone", "urgent-help", PC, "Patients should be advised to consult their healthcare provider immediately if they feel faint, lose consciousness or have heart palpitations. Patients should be counseled not to take FANAPT with other drugs that cause QT interval prolongation", "Consult your healthcare provider immediately if you feel faint, lose consciousness or have heart palpitations. Do not take iloperidone with other medicines that lengthen the QT interval (a heart rhythm measurement)."),
    c("iloperidone", "interactions", PC, "Patients should be told to inform their healthcare provider that they are taking FANAPT before any new drug is taken.", "Tell your healthcare provider that you are taking iloperidone before you take any new medicine."),
    c("iloperidone", "urgent-help", PC, "Counsel patients and caregivers about a potentially fatal adverse reaction, NMS, that has been reported with administration of antipsychotic drugs, including FANAPT. Advise patients and caregivers to contact the healthcare provider or to report to the emergency room if they experience signs and symptoms of NMS", "Antipsychotic medicines, including iloperidone, have been linked to a potentially fatal reaction called neuroleptic malignant syndrome (NMS). Contact your healthcare provider or go to the emergency room if you or a caregiver notice signs of NMS."),
    c("iloperidone", "side-effects", PC, "Counsel patients on the signs and symptoms of tardive dyskinesia and to contact their healthcare provider if these abnormal movements occur", "Tardive dyskinesia is a problem of abnormal movements that can be linked to antipsychotic medicines. Contact your healthcare provider if you notice abnormal movements."),
    c("iloperidone", "side-effects", PC, "Educate patients of metabolic changes, how to recognize symptoms of hyperglycemia and diabetes mellitus, and the need for specific monitoring, including blood glucose, lipids, and weight. Patients should be counseled that weight gain has occurred during treatment with FANAPT", "Iloperidone can cause metabolic changes. Your healthcare provider should explain how to recognise the symptoms of high blood sugar (hyperglycemia) and diabetes, and why your blood sugar, blood fats (lipids) and weight need to be monitored. Weight gain has occurred during treatment."),
    c("iloperidone", "precaution", PC, "Educate patients about the risk of orthostatic hypotension and syncope, particularly at the time of initiating treatment, re-initiating treatment, or increasing the dose", "It can cause low blood pressure when you stand up (orthostatic hypotension) and fainting (syncope), particularly when treatment is started or restarted, or when the dose is increased."),
    c("iloperidone", "monitoring", PC, "Advise patients with a pre-existing low WBC or a history of drug induced leukopenia/neutropenia that they should have their CBC monitored while taking FANAPT", "If you already have a low white blood cell count, or have had a drop in white cells caused by a medicine (leukopenia or neutropenia), you should have your blood count (CBC) monitored while taking iloperidone."),
    c("iloperidone", "precaution", PC, "Educate patients regarding appropriate care in avoiding overheating and dehydration", "Take care to avoid overheating and dehydration."),
    c("iloperidone", "precaution", PC, "Caution patients about performing activities requiring mental alertness, such as operating hazardous machinery or operating a motor vehicle, until they are reasonably certain that FANAPT therapy does not affect them adversely", "Do not do activities that need you to be mentally alert, such as operating hazardous machinery or driving, until you are reasonably certain that iloperidone does not affect you badly."),
    c("iloperidone", "precaution", PC, "Instruct patients to tell their ophthalmologist about their use of FANAPT before cataract surgery or other procedures involving the eyes, even if the patient is no longer taking FANAPT", "Tell your eye doctor (ophthalmologist) that you use iloperidone before cataract surgery or other eye procedures, even if you are no longer taking it."),
    c("iloperidone", "precaution", PC, "Advise patients that third trimester use of FANAPT may cause extrapyramidal and/or withdrawal symptoms in a neonate. Advise patients to notify their healthcare provider with known or suspected pregnancy", "Using iloperidone in the third trimester of pregnancy may cause extrapyramidal symptoms (movement problems) and/or withdrawal symptoms in a newborn. Tell your healthcare provider if you know or suspect you are pregnant."),
    c("iloperidone", "precaution", PC, "Advise women not to breastfeed during treatment with FANAPT", "Women should not breastfeed during treatment with iloperidone."),
    c("iloperidone", "interactions", PC, "Advise patients to inform their healthcare provider if they are taking, or plan to take, any prescription or over-the-counter drugs, since there is a potential for interactions", "Tell your healthcare provider about any prescription or over-the-counter medicine you are taking or plan to take, because interactions are possible."),
    c("iloperidone", "precaution", PC, "Patients should be advised to avoid alcohol while taking FANAPT.", "Avoid alcohol while taking iloperidone."),

    /* ---- pimavanserin capsules ---- */
    c("pimavanserin", "used-for", IND, "NUPLAZID is an atypical antipsychotic indicated for the treatment of hallucinations and delusions associated with Parkinson's disease psychosis.", "Pimavanserin is an atypical antipsychotic used to treat hallucinations and delusions (false beliefs) associated with Parkinson's disease psychosis."),
    c("pimavanserin", "precaution", BOX, "Elderly patients with dementia-related psychosis treated with antipsychotic drugs are at an increased risk of death. NUPLAZID is not approved for the treatment of patients with dementia who experience psychosis unless their hallucinations and delusions are related to Parkinson's disease", "Elderly people with dementia-related psychosis who are treated with antipsychotic medicines are at an increased risk of death. Pimavanserin is not approved for treating psychosis in people with dementia unless their hallucinations and delusions are related to Parkinson's disease."),
    c("pimavanserin", "contraindication", CONTRA, "NUPLAZID is contraindicated in patients with a history of a hypersensitivity reaction to pimavanserin or any of its components. Rash, urticaria, and reactions consistent with angioedema (e.g., tongue swelling, circumoral edema, throat tightness, and dyspnea) have been reported", "Pimavanserin must not be used if you have ever had a hypersensitivity (allergic) reaction to it or any of its components. Rash, hives (urticaria) and reactions consistent with angioedema (for example swelling of the tongue or around the mouth, throat tightness and shortness of breath) have been reported."),
    c("pimavanserin", "interactions", PC, "Advise patients to inform their healthcare providers if there are any changes to their current prescription or over-the-counter medications, since there is a potential for drug interactions", "Tell your healthcare provider about any change to your prescription or over-the-counter medicines, because drug interactions are possible."),
    c("pimavanserin", "how-to-take", PC, "Advise patients to take the capsule whole or sprinkled over a tablespoon (15 mL) of applesauce, yogurt, pudding, or a liquid nutritional supplement. Advise patients to consume the drug/food mixture immediately and not to store for future use", "Take the capsule whole, or sprinkle its contents over a tablespoon (15 mL) of applesauce, yogurt, pudding or a liquid nutritional supplement. Eat or drink the mixture immediately and do not store it for later."),

    /* ---- naltrexone tablets ---- */
    c("naltrexone", "used-for", IND, "Naltrexone Hydrochloride Tablets, USP are indicated in the treatment of alcohol dependence and for the blockade of the effects of exogenously administered opioids.", "Naltrexone is used to treat alcohol dependence and to block the effects of opioids taken from outside the body (exogenous opioids)."),
    c("naltrexone", "precaution", IND, "Naltrexone Hydrochloride Tablets, USP have not been shown to provide any therapeutic benefit except as part of an appropriate plan of management for the addictions.", "Naltrexone has not been shown to give any benefit except as part of an appropriate plan for managing the addiction."),
    c("naltrexone", "contraindication", CONTRA, "Naltrexone hydrochloride is contraindicated in: 1. Patients receiving opioid analgesics. 2. Patients currently dependent on opioids, including those currently maintained on opiate agonists (e.g., methadone) or partial agonists (e.g., buprenorphine).", "Naltrexone must not be used by people receiving opioid painkillers, or people who are currently dependent on opioids, including those maintained on methadone or buprenorphine."),
    c("naltrexone", "contraindication", CONTRA, "4. Any individual who has failed the naloxone challenge test or who has a positive urine screen for opioids. 5. Any individual with a history of sensitivity to naltrexone hydrochloride or any other components of this product.", "It must not be used by anyone who has failed the naloxone challenge test (a test for opioid dependence) or has a positive urine screen for opioids, or who has a history of sensitivity (allergy) to naltrexone or any other component of the product."),
    c("naltrexone", "how-to-take", DOSE, "To reduce the risk of precipitated withdrawal in patients dependent on opioids, or exacerbation of a preexisting subclinical withdrawal syndrome, opioid-dependent patients, including those being treated for alcohol dependence, should be opioid-free (including tramadol) before starting naltrexone hydrochloride tablets treatment. An opioid-free interval of a minimum of 7 to 10 days is recommended for patients previously dependent on short-acting opioids.", "To reduce the risk of sudden withdrawal symptoms, people who were dependent on opioids, including those being treated for alcohol dependence, should be opioid-free (including tramadol) before starting naltrexone. A gap of at least 7 to 10 days without opioids is recommended for people previously dependent on short-acting opioids."),
    c("naltrexone", "precaution", PC, "You should carry identification to alert medical personnel to the fact that you are taking naltrexone hydrochloride.", "Carry identification to alert medical staff that you are taking naltrexone."),
    c("naltrexone", "precaution", PC, "If you require medical treatment, be sure to tell the treating physician that you are receiving naltrexone hydrochloride therapy.", "If you need medical treatment, be sure to tell the treating doctor that you are taking naltrexone."),
    c("naltrexone", "urgent-help", PC, "Advise patients that if they previously used opioids, they may be more sensitive to lower doses of opioids and at risk of accidental overdose should they use opioids after naltrexone hydrochloride treatment is discontinued or temporarily interrupted. It is important that patients inform family members and the people closest to the patient of this increased sensitivity to opioids and the risk of overdose.", "If you used opioids before, you may be more sensitive to lower doses of opioids and at risk of accidental overdose if you use opioids after naltrexone is stopped or temporarily interrupted. It is important to tell family members and the people closest to you about this increased sensitivity and the risk of overdose."),
    c("naltrexone", "urgent-help", WARN, "This could result in potentially life-threatening opioid intoxication (respiratory compromise or arrest, circulatory collapse, etc.) if the patient uses previously tolerated doses of opioids. Cases of opioid overdose with fatal outcomes have been reported in patients after discontinuing treatment.", "Using the opioid doses you tolerated before could cause potentially life-threatening opioid intoxication (breathing trouble or stopping, collapse of the circulation and so on). Cases of fatal opioid overdose have been reported in people after they stopped treatment."),
    c("naltrexone", "interactions", INTER, "Patients taking naltrexone hydrochloride may not benefit from opioid containing medicines, such as cough and cold preparations, antidiarrheal preparations, and opioid analgesics.", "People taking naltrexone may not benefit from medicines that contain an opioid, such as cough and cold preparations, anti-diarrhoea preparations and opioid painkillers."),
    c("naltrexone", "interactions", INTER, "The safety and efficacy of concomitant use of naltrexone hydrochloride and disulfiram is unknown, and the concomitant use of two potentially hepatotoxic medications is not ordinarily recommended unless the probable benefits outweigh the known risks.", "The safety and effectiveness of taking naltrexone together with disulfiram is unknown. Taking two medicines that can both harm the liver is not ordinarily recommended unless the likely benefits outweigh the known risks."),
    c("naltrexone", "interactions", INTER, "Lethargy and somnolence have been reported following doses of naltrexone hydrochloride and thioridazine.", "Lethargy (extreme tiredness) and sleepiness have been reported after doses of naltrexone and thioridazine."),
    c("naltrexone", "interactions", INTER, "Studies to evaluate possible interactions between naltrexone hydrochloride and drugs other than opiates have not been performed. Consequently, caution is advised if the concomitant administration of naltrexone hydrochloride and other drugs is required.", "Studies of possible interactions between naltrexone and medicines other than opiates have not been done, so caution is advised if naltrexone has to be taken with other medicines."),
    c("naltrexone", "side-effects", ADVERSE, "most patients tolerated naltrexone hydrochloride well. In these studies, a total of 93 patients received naltrexone hydrochloride at a dose of 50 mg once daily. Five of these patients discontinued naltrexone hydrochloride because of nausea. No serious adverse events were reported during these two trials.", "In two alcohol-dependence trials, most people tolerated naltrexone well. Of 93 people who took 50 mg once a day, five stopped because of nausea. No serious adverse events were reported in those trials."),
    c("naltrexone", "side-effects", ADVERSE, "placebo-controlled studies employing up to five-fold higher doses of naltrexone hydrochloride (up to 300 mg per day) than that recommended for use in opiate receptor blockade have shown that naltrexone hydrochloride causes hepatocellular injury in a substantial proportion of patients exposed at higher doses", "In studies using doses up to five times higher than recommended (up to 300 mg a day), naltrexone caused hepatocellular injury (liver cell damage) in a substantial proportion of people exposed at the higher doses."),

    /* ---- acamprosate delayed-release tablets ---- */
    c("acamprosate", "used-for", IND, "Acamprosate calcium delayed-release tablets are indicated for the maintenance of abstinence from alcohol in patients with alcohol dependence who are abstinent at treatment initiation. Treatment with acamprosate calcium delayed-release tablets should be part of a comprehensive management program that includes psychosocial support.", "Acamprosate is used to help people with alcohol dependence who are already abstinent when they start it to stay off alcohol. Treatment should be part of a comprehensive management program that includes psychosocial support."),
    c("acamprosate", "precaution", IND, "The efficacy of acamprosate calcium delayed-release tablets in promoting abstinence has not been demonstrated in subjects who have not undergone detoxification and not achieved alcohol abstinence prior to beginning acamprosate calcium delayed-release tablets treatment.", "It has not been shown to help people to stop drinking if they have not first been through detoxification and achieved abstinence from alcohol before starting."),
    c("acamprosate", "contraindication", CONTRA, "Acamprosate calcium is contraindicated in patients who previously have exhibited hypersensitivity to acamprosate calcium or any of its components.", "Acamprosate must not be used by people who have previously shown hypersensitivity (allergy) to it or any of its components."),
    c("acamprosate", "contraindication", CONTRA, "Acamprosate calcium is contraindicated in patients with severe renal impairment (creatinine clearance of ≤ 30 mL/min)", "Acamprosate must not be used by people with severe kidney impairment (creatinine clearance of 30 mL/min or less)."),
    c("acamprosate", "precaution", PC, "A lower dose is recommended for patients with moderate renal impairment.", "A lower dose is recommended for people with moderate kidney impairment."),
    c("acamprosate", "urgent-help", PC, "Families and caregivers of patients being treated with acamprosate calcium should be alerted to the need to monitor patients for the emergence of symptoms of depression or suicidality, and to report such symptoms to the patient's health care provider", "Families and caregivers should watch for symptoms of depression or suicidal thoughts and behaviour in the person taking acamprosate, and report them to the person's health care provider."),
    c("acamprosate", "precaution", PC, "Use of acamprosate calcium does not eliminate or diminish withdrawal symptoms", "Acamprosate does not remove or reduce alcohol withdrawal symptoms."),
    c("acamprosate", "precaution", PC, "Advise patients to notify their physician if they become pregnant or intend to become pregnant during therapy. Advise patients to notify their physician if they are breast-feeding.", "Tell your doctor if you become pregnant or intend to become pregnant during treatment, and if you are breast-feeding."),
    c("acamprosate", "how-to-take", PC, "Advise patients to continue acamprosate calcium therapy as directed, even in the event of relapse and remind them to discuss any renewed drinking with their physicians.", "Keep taking acamprosate as directed even if you start drinking again, and discuss any renewed drinking with your doctor."),
    c("acamprosate", "how-to-take", DOSE, "The recommended dose of acamprosate calcium delayed-release tablets is two 333 mg tablets (each dose should total 666 mg) taken three times daily. A lower dose may be effective in some patients.", "The label gives a recommended dose of two 333 mg tablets (666 mg in total) taken three times a day. A lower dose may be effective in some people. Your own dose is set by your prescriber.", ["US prescribing information, which is written for clinicians: this restates it in plain words.", "These are the doses in the US label for the delayed-release tablets. Do not use them to change your own dose.", "US label only: Indian approval, strengths and warnings may differ."]),
    c("acamprosate", "how-to-take", DOSE, "Although dosing may be done without regard to meals, dosing with meals was employed during clinical trials and is suggested in those patients who regularly eat three meals daily.", "The tablets may be taken without regard to meals, but they were taken with meals in the clinical trials, and this is suggested for people who regularly eat three meals a day."),
    c("acamprosate", "how-to-take", DOSE, "Treatment with acamprosate calcium delayed-release tablets should be initiated as soon as possible after the period of alcohol withdrawal, when the patient has achieved abstinence, and should be maintained if the patient relapses.", "Treatment should start as soon as possible after alcohol withdrawal, once abstinence has been achieved, and should be continued if you relapse."),
    c("acamprosate", "interactions", INTER, "Acamprosate does not affect the pharmacokinetics of alcohol. The pharmacokinetics of acamprosate are not affected by alcohol, diazepam, or disulfiram, and clinically important interactions between naltrexone and acamprosate were not observed", "The label says acamprosate does not change how the body handles alcohol, and that alcohol, diazepam and disulfiram do not change how the body handles acamprosate. No clinically important interaction between naltrexone and acamprosate was seen. This is not a list of medicines that are safe to combine with it.", ["US prescribing information, which is written for clinicians: this restates it in plain words.", "Not being named, or not being reported, does not make a combination safe. Ask your pharmacist.", "US label only: Indian approval, strengths and warnings may differ."]),
    c("acamprosate", "side-effects", ADVERSE, "Common adverse events that occurred in any acamprosate calcium treatment group at a rate of 3% or greater and greater than the placebo group in controlled clinical trials with spontaneously reported adverse events are: accidental injury, asthenia, pain, anorexia, diarrhea, flatulence, nausea, anxiety, depression, dizziness, dry mouth, insomnia, paresthesia, pruritus and sweating", "Common side effects in controlled trials (in 3% or more of people and more often than with a dummy tablet) were: accidental injury, weakness (asthenia), pain, loss of appetite, diarrhoea, wind (flatulence), nausea, anxiety, depression, dizziness, dry mouth, insomnia, tingling or numbness (paresthesia), itching and sweating."),
    c("acamprosate", "side-effects", ADVERSE, "Clinically significant serious adverse reactions associated with acamprosate calcium described elsewhere in labeling include suicidality and depression and acute kidney failure", "Serious reactions linked to acamprosate described elsewhere in the label include suicidal thoughts and behaviour, depression and acute kidney failure."),

    /* ---- guanfacine tablets (immediate release, for high blood pressure) ---- */
    c("guanfacine", "used-for", IND, "Guanfacine tablets are indicated in the management of hypertension. Guanfacine may be given alone or in combination with other antihypertensive agents, especially thiazide-type diuretics.", "This label for guanfacine tablets says they are used to manage high blood pressure (hypertension), alone or with other blood pressure medicines, especially thiazide-type diuretics (water tablets). It does not describe other uses of guanfacine.", ["This is the label for guanfacine tablets for high blood pressure. Other uses and forms of guanfacine are not covered.", "US prescribing information, which is written for clinicians: this restates it in plain words.", "US label only: Indian approval, strengths and warnings may differ."]),
    c("guanfacine", "contraindication", CONTRA, "Guanfacine tablets are contraindicated in patients with known hypersensitivity to guanfacine hydrochloride.", "Guanfacine tablets must not be used by people with known hypersensitivity (allergy) to guanfacine."),
    c("guanfacine", "how-to-take", DOSE, "The recommended initial dose of guanfacine tablets when given alone or in combination with another antihypertensive drug is 1 mg daily given at bedtime to minimize somnolence.", "For high blood pressure, the label gives a recommended starting dose of 1 mg a day, taken at bedtime to reduce sleepiness (somnolence). Your own dose is set by your prescriber.", ["This is the starting dose in the US label for high blood pressure. Do not use it to change your own dose.", "US prescribing information, which is written for clinicians: this restates it in plain words.", "US label only: Indian approval, strengths and warnings may differ."]),
    c("guanfacine", "stopping", DOSE, "The frequency of rebound hypertension is low, but it can occur. When rebound occurs, it does so after 2 to 4 days, which is delayed compared with clonidine hydrochloride.", "Rebound hypertension (a rise in blood pressure after stopping) is uncommon but can occur. When it does, it happens 2 to 4 days later, which is later than with clonidine."),
    c("guanfacine", "side-effects", ADVERSE, "Adverse reactions noted with guanfacine hydrochloride are similar to those of other drugs of the central α2-adrenoreceptor agonist class: dry mouth, sedation (somnolence), weakness (asthenia), dizziness, constipation, and impotence. While the reactions are common, most are mild and tend to disappear on continued dosing.", "Side effects are similar to other medicines of the same group: dry mouth, sedation (sleepiness), weakness, dizziness, constipation and impotence. They are common, but most are mild and tend to disappear with continued dosing."),
    c("guanfacine", "side-effects", ADVERSE, "Skin rash with exfoliation has been reported in a few cases; although clear cause and effect relationships to guanfacine could not be established, should a rash occur, guanfacine should be discontinued and the patient monitored appropriately.", "A skin rash with peeling (exfoliation) has been reported in a few cases. A clear cause-and-effect link to guanfacine could not be shown, but if a rash occurs, guanfacine should be stopped and you should be monitored appropriately."),

    /* ---- galantamine tablets ---- */
    c("galantamine", "used-for", IND, "Galantamine tablets are indicated for the treatment of mild to moderate dementia of the Alzheimer’s type.", "Galantamine is used to treat mild to moderate dementia of the Alzheimer's type."),
    c("galantamine", "contraindication", CONTRA, "Galantamine tablets are contraindicated in patients with known hypersensitivity to galantamine hydrobromide or to any excipients used in the formulation.", "Do not take it if you are known to be hypersensitive (allergic) to galantamine hydrobromide or to any other ingredient in the tablets."),
    c("galantamine", "urgent-help", PC, "Advise patients and caregivers to discontinue galantamine tablets and seek immediate medical attention at the first appearance of skin rash", "Stop taking galantamine and seek immediate medical attention at the first appearance of a skin rash."),
    c("galantamine", "how-to-take", PC, "Galantamine tablets should be administered twice per day, preferably with the morning and evening meals.", "Galantamine tablets should be taken twice a day, preferably with the morning and evening meals."),
    c("galantamine", "how-to-take", PC, "Dose escalation (dose increases) should follow a minimum of four weeks at prior dose. If therapy has been interrupted for more than three days, the patient should be restarted with the lowest dose and then re-titrated to an appropriate dosage", "Dose increases should follow at least four weeks at the previous dose. If treatment has been interrupted for more than three days, it should be restarted at the lowest dose and then built up again to an appropriate dose."),
    c("galantamine", "how-to-take", PC, "Advise patients and caregivers to ensure adequate fluid intake during treatment", "Make sure you drink enough fluids during treatment."),
    c("galantamine", "side-effects", PC, "Advise patients and caregivers that the most frequent adverse events associated with use of the drug can be minimized by following the recommended dosage and administration.", "The most frequent side effects can be minimised by following the recommended dose and way of taking the medicine."),
    c("galantamine", "interactions", INTER, "Galantamine has the potential to interfere with the activity of anticholinergic medications", "Galantamine may interfere with the activity of anticholinergic medicines (medicines with drying effects)."),
    c("galantamine", "interactions", INTER, "A synergistic effect is expected when cholinesterase inhibitors are given concurrently with succinylcholine, other cholinesterase inhibitors, similar neuromuscular blocking agents or cholinergic agonists such as bethanechol", "A combined, stronger effect is expected if galantamine (a cholinesterase inhibitor) is given together with succinylcholine, other cholinesterase inhibitors, similar muscle-relaxing medicines used in anaesthesia, or cholinergic agonists such as bethanechol."),
    c("galantamine", "side-effects", ADVERSE, "The most common adverse reactions in galantamine-treated patients from double-blind clinical trials (≥ 5%) were nausea, vomiting, diarrhea, dizziness, headache, and decreased appetite.", "In trials, the most common side effects (in 5% or more of people) were nausea, vomiting, diarrhoea, dizziness, headache and decreased appetite."),

    /* ---- rivastigmine capsules ---- */
    c("rivastigmine", "used-for", IND, "Rivastigmine tartrate capsules are indicated for the treatment of mild-to-moderate dementia of the Alzheimer's type (AD).", "Rivastigmine capsules are used to treat mild-to-moderate dementia of the Alzheimer's type."),
    c("rivastigmine", "used-for", IND, "Rivastigmine tartrate capsules are indicated for the treatment of mild-to-moderate dementia associated with Parkinson’s disease (PD).", "They are also used to treat mild-to-moderate dementia associated with Parkinson's disease."),
    c("rivastigmine", "contraindication", CONTRA, "Rivastigmine tartrate capsules are contraindicated in patients with: known hypersensitivity to rivastigmine, other carbamate derivatives or other components of the formulation [see Description (11)] a previous history of application site reaction with rivastigmine transdermal patch suggestive of allergic contact dermatitis, in the absence of negative allergy testing", "Do not take them if you are known to be hypersensitive (allergic) to rivastigmine, other carbamate-type medicines or other components of the capsules, or if you previously had a skin reaction to the rivastigmine patch that suggested allergic contact dermatitis (an allergic skin rash), unless allergy testing was negative."),
    c("rivastigmine", "how-to-take", DOSE, "Rivastigmine tartrate capsules should be taken with meals in divided doses in the morning and evening", "Take the capsules with meals, in divided doses in the morning and evening."),
    c("rivastigmine", "stopping", PC, "It is critical to inform caregivers that if therapy has been interrupted for more than several days, the next dose should not be administered until they have discussed this with the physician", "If treatment has been interrupted for more than several days, do not give the next dose until you have discussed it with the doctor."),
    c("rivastigmine", "side-effects", PC, "Caregivers should be advised of the high incidence of nausea and vomiting associated with the use of the drug along with the possibility of anorexia and weight loss. Caregivers should be encouraged to monitor for these adverse events and inform the physician if they occur.", "Nausea and vomiting are common with rivastigmine, and loss of appetite (anorexia) and weight loss are possible. Caregivers should watch for these and tell the doctor if they occur."),
    c("rivastigmine", "urgent-help", PC, "Caregivers and patients should be advised that allergic skin reactions have been reported in association with rivastigmine tartrate regardless of formulation (capsules, oral solution or transdermal patch). In case of skin reaction while taking rivastigmine tartrate, patients should consult with their physician immediately", "Allergic skin reactions have been reported with rivastigmine in every form (capsules, oral solution or skin patch). If a skin reaction occurs while taking it, consult your doctor immediately."),
    c("rivastigmine", "side-effects", PC, "Caregivers and patients should be advised that cholinomimetics, including rivastigmine, may exacerbate or induce extrapyramidal symptoms. Worsening in patients with Parkinson’s disease, including an increased incidence or intensity of tremor, has been observed", "Medicines that act like acetylcholine (cholinomimetics), including rivastigmine, may worsen or cause extrapyramidal symptoms (movement problems). Worsening in people with Parkinson's disease, including more frequent or stronger tremor, has been observed."),
    c("rivastigmine", "interactions", INTER, "Due to the risk of additive extrapyramidal adverse reactions, the concomitant use of metoclopramide and rivastigmine tartrate is not recommended.", "Because the movement-problem side effects can add up, taking metoclopramide together with rivastigmine is not recommended."),
    c("rivastigmine", "interactions", INTER, "Rivastigmine tartrate may increase the cholinergic effects of other cholinomimetic medications and may also interfere with the activity of anticholinergic medications (e.g., oxybutynin, tolterodine). Concomitant use of rivastigmine tartrate with medications having these pharmacologic effects is not recommended unless deemed clinically necessary", "Rivastigmine may increase the effects of other cholinomimetic medicines and may also interfere with anticholinergic (drying) medicines such as oxybutynin and tolterodine. Using it with medicines that have these effects is not recommended unless clinically necessary."),
    c("rivastigmine", "interactions", INTER, "Additive bradycardic effects resulting in syncope may occur when rivastigmine tartrate is used concomitantly with beta-blockers", "Slowing of the heartbeat (bradycardia) can add up, resulting in fainting (syncope), when rivastigmine is used with beta-blockers."),
    c("rivastigmine", "precaution", PC, "Advise patients to notify their healthcare provider if they are pregnant or plan to become pregnant.", "Tell your healthcare provider if you are pregnant or plan to become pregnant."),
    c("rivastigmine", "side-effects", ADVERSE, "Most common adverse reactions (greater than 5% and 2 times greater than placebo): nausea, vomiting, anorexia, dyspepsia, and asthenia", "The most common side effects (in more than 5% of people and 2 times as often as with a dummy tablet) were nausea, vomiting, loss of appetite (anorexia), indigestion (dyspepsia) and weakness (asthenia)."),

    /* ---- tasimelteon capsules ---- */
    c("tasimelteon", "what-it-is", IND, "Tasimelteon capsules are a melatonin receptor agonist.", "Tasimelteon is a melatonin receptor agonist (it acts on the same body receptors as the sleep hormone melatonin)."),
    c("tasimelteon", "used-for", IND, "Tasimelteon capsules are indicated for the treatment of Non-24 in adults.", "Tasimelteon is used to treat Non-24-Hour Sleep-Wake Disorder (Non-24, a body-clock disorder) in adults."),
    c("tasimelteon", "contraindication", CONTRA, "None.", "The label lists no situations in which it must never be used. That does not mean it is safe for everyone."),
    c("tasimelteon", "precaution", PC, "Advise patients to limit their activities to preparing for going to bed after taking tasimelteon capsules because tasimelteon can potentially impair the performance of activities requiring complete mental alertness", "After taking it, limit your activities to getting ready for bed, because tasimelteon can impair activities that need complete mental alertness."),
    c("tasimelteon", "how-to-take", PC, "Advise patients to take tasimelteon capsules without food. Advise patients to take tasimelteon capsules before bedtime at the same time every night. Advise patients to skip the dose that night if they cannot take tasimelteon capsules at approximately the same time on a given night. Advise patients to swallow tasimelteon capsules whole.", "Take the capsules without food, before bedtime, at the same time every night. If you cannot take it at about the same time on a given night, skip the dose that night. Swallow the capsules whole."),
    c("tasimelteon", "how-to-take", DOSE, "The recommended dosage of tasimelteon capsules in adults is 20 mg one hour before bedtime, at the same time every night.", "The label gives a recommended adult dose of 20 mg one hour before bedtime, at the same time every night. Your own dose is set by your prescriber.", ["These are the doses in the US label. Do not use them to change your own dose.", "US prescribing information, which is written for clinicians: this restates it in plain words.", "US label only: Indian approval, strengths and warnings may differ."]),
    c("tasimelteon", "onset", PC, "Advise patients that because of individual differences in circadian rhythms, daily use for several weeks or months may be necessary before benefit from tasimelteon capsules is observed", "Because body clocks differ from person to person, daily use for several weeks or months may be needed before a benefit is seen.", ["This is stated for the treatment of Non-24-Hour Sleep-Wake Disorder.", "US prescribing information, which is written for clinicians: this restates it in plain words.", "US label only: Indian approval, strengths and warnings may differ."], "onset-works-gradually"),
    c("tasimelteon", "interactions", INTER, "Avoid use of tasimelteon in combination with fluvoxamine or other strong CYP1A2 inhibitors because of a potentially large increase in tasimelteon exposure and greater risk of adverse reactions", "Avoid using tasimelteon with fluvoxamine or other strong CYP1A2 inhibitors, because they could greatly increase the amount of tasimelteon in the body and the risk of side effects."),
    c("tasimelteon", "interactions", INTER, "Avoid use of tasimelteon in combination with rifampin or other CYP3A4 inducers because of a potentially large decrease in tasimelteon exposure with reduced efficacy", "Avoid using tasimelteon with rifampin or other CYP3A4 inducers, because they could greatly reduce the amount of tasimelteon in the body and so its effect."),
    c("tasimelteon", "side-effects", ADVERSE, "The most common adverse reactions (incidence >5% and at least twice as high on tasimelteon than on placebo) were headache, increased alanine aminotransferase, nightmares or unusual dreams, and upper respiratory or urinary tract infection", "The most common side effects (in more than 5% of people and at least twice as often as with a dummy tablet) were headache, a raised liver enzyme (alanine aminotransferase) on blood tests, nightmares or unusual dreams, and upper respiratory or urinary tract infection."),

    /* ---- liothyronine (triiodothyronine, T3) tablets ---- */
    c("triiodothyronine", "used-for", IND, "Liothyronine sodium is an L-triiodothyronine (T3) indicated for: Hypothyroidism: As replacement in primary (thyroidal), secondary (pituitary), and tertiary (hypothalamic) congenital or acquired hypothyroidism", "Liothyronine is a thyroid hormone (T3). This label lists its use as replacement therapy in hypothyroidism (an underactive thyroid), whatever the part of the body behind it and whether it was present from birth or acquired. It does not describe use as an add-on in depression.", ["This is the US label for liothyronine tablets. Other uses, such as an add-on in depression, are not covered.", "US prescribing information, which is written for clinicians: this restates it in plain words.", "US label only: Indian approval, strengths and warnings may differ."]),
    c("triiodothyronine", "precaution", BOX, "Thyroid hormones, including liothyronine sodium, either alone or with other therapeutic agents, should not be used for the treatment of obesity or for weight loss. In euthyroid patients, doses within the range of daily hormonal requirements are ineffective for weight reduction.", "Thyroid hormones, including liothyronine, should not be used for obesity or weight loss, alone or with other medicines. In people with normal thyroid function (euthyroid), doses in the range of the body's daily hormone needs do not cause weight loss."),
    c("triiodothyronine", "urgent-help", BOX, "Larger doses may produce serious or even life-threatening manifestations of toxicity, particularly when given in association with sympathomimetic amines such as those used for their anorectic effects", "Larger doses may cause serious or even life-threatening toxicity, particularly when taken with sympathomimetic amines such as those used to reduce appetite."),
    c("triiodothyronine", "contraindication", CONTRA, "Liothyronine sodium tablets are contraindicated in patients with uncorrected adrenal insufficiency", "Liothyronine must not be used by people with uncorrected adrenal insufficiency (underactive adrenal glands that are not being treated)."),
    c("triiodothyronine", "how-to-take", PC, "Instruct patients that liothyronine sodium tablets should only be taken as directed by their healthcare provider.", "Take liothyronine only as directed by your healthcare provider."),
    c("triiodothyronine", "how-to-take", PC, "Inform patients that the liothyronine in liothyronine sodium tablets are intended to replace a hormone that is normally produced by the thyroid gland. Generally replacement therapy is to be taken for life.", "Liothyronine replaces a hormone that the thyroid gland normally makes. Replacement therapy is generally taken for life."),
    c("triiodothyronine", "precaution", PC, "Inform patients that liothyronine sodium tablets should not be used as a primary or adjunctive therapy in a weight control program.", "Liothyronine should not be used as a main or add-on treatment in a weight control program."),
    c("triiodothyronine", "interactions", PC, "Instruct patients to notify their healthcare provider if they are taking any other medications, including prescription and over-the-counter preparations.", "Tell your healthcare provider about any other medicines you take, including prescription and over-the-counter ones."),
    c("triiodothyronine", "interactions", PC, "Instruct patients to notify their healthcare provider of any other medical conditions, particularly heart disease, diabetes, clotting disorders, and adrenal or pituitary gland problems, as the dose of medications used to control these other conditions may need to be adjusted while taking liothyronine sodium tablets. If patents are taking anticoagulants (blood thinners), their clotting status should be checked frequently.", "Tell your healthcare provider about any other medical conditions, particularly heart disease, diabetes, clotting disorders, and adrenal or pituitary gland problems, because the doses of medicines for those conditions may need adjusting while you take liothyronine. If you take anticoagulants (blood thinners), your clotting status should be checked frequently."),
    c("triiodothyronine", "precaution", PC, "Instruct patients to notify their physician or dentist if they are taking liothyronine sodium tablets prior to any surgery.", "Tell your doctor or dentist that you take liothyronine before any surgery."),
    c("triiodothyronine", "precaution", PC, "Instruct patients to notify their healthcare provider should they become pregnant or breastfeeding or are thinking of becoming pregnant, while taking liothyronine sodium tablets.", "Tell your healthcare provider if you become pregnant, are breastfeeding, or are thinking of becoming pregnant while taking liothyronine."),
    c("triiodothyronine", "urgent-help", PC, "Instruct patients to notify their healthcare provider if they experience any of the following symptoms: rapid or irregular heartbeat, chest pain, shortness of breath, leg cramps, headache, nervousness, irritability, sleeplessness, tremors, change in appetite, weight gain or loss, vomiting, diarrhea, excessive sweating, heat intolerance, fever, changes in menstrual periods, hives or skin rash, or any other unusual medical event", "Tell your healthcare provider if you get a rapid or irregular heartbeat, chest pain, shortness of breath, leg cramps, headache, nervousness, irritability, sleeplessness, tremors, a change in appetite, weight gain or loss, vomiting, diarrhoea, excessive sweating, heat intolerance, fever, changes in your periods, hives or a skin rash, or any other unusual medical event."),
    c("triiodothyronine", "side-effects", PC, "Inform patients that partial hair loss may occur rarely during the first few months of liothyronine sodium tablets therapy; this is usually temporary", "Partial hair loss may occur rarely during the first few months of treatment; this is usually temporary."),
    c("triiodothyronine", "side-effects", ADVERSE, "Adverse reactions associated with Liothyronine sodium tablets therapy are primarily those of hyperthyroidism due to therapeutic overdosage", "Side effects are mainly those of hyperthyroidism (an overactive thyroid) caused by taking too much of the medicine."),

    /* ---- diphenhydramine: US over-the-counter sleep-aid label (Drug Facts) ---- */
    c("diphenhydramine", "used-for", IND, "for relief of occasional sleeplessness reduces time to fall asleep if you have difficulty falling asleep", "This over-the-counter sleep aid label says it is for relief of occasional sleeplessness and reduces the time to fall asleep if you have difficulty falling asleep. It does not describe other uses of diphenhydramine.", ["This is a US over-the-counter sleep-aid label. Other uses and forms of diphenhydramine are not covered.", "US label only: Indian approval, strengths and warnings may differ.", "General information, not advice for any one person."]),
    c("diphenhydramine", "precaution", WARN, "Do not use for children under 12 years of age with any other product containing diphenhydramine, even one used on skin", "Do not use it for children under 12 years of age, or with any other product containing diphenhydramine, even one used on the skin.", ["This is a US over-the-counter sleep-aid label. Other uses and forms of diphenhydramine are not covered.", "US label only: Indian approval, strengths and warnings may differ.", "General information, not advice for any one person."]),
    c("diphenhydramine", "precaution", WARN, "Ask a doctor before use if you have a breathing problem such as emphysema or chronic bronchitis glaucoma difficulty in urination due to enlargement of the prostate gland", "Ask a doctor before use if you have a breathing problem such as emphysema or chronic bronchitis, glaucoma, or difficulty passing urine because of an enlarged prostate gland.", ["This is a US over-the-counter sleep-aid label. Other uses and forms of diphenhydramine are not covered.", "US label only: Indian approval, strengths and warnings may differ.", "General information, not advice for any one person."]),
    c("diphenhydramine", "interactions", WARN, "Ask a doctor or pharmacist before use if you are taking sedatives or tranquilizers.", "Ask a doctor or pharmacist before use if you are taking sedatives or tranquillisers.", ["This is a US over-the-counter sleep-aid label. Other uses and forms of diphenhydramine are not covered.", "US label only: Indian approval, strengths and warnings may differ.", "General information, not advice for any one person."]),
    c("diphenhydramine", "precaution", WARN, "When using this product avoid alcoholic beverages.", "While using this product, avoid alcoholic drinks.", ["This is a US over-the-counter sleep-aid label. Other uses and forms of diphenhydramine are not covered.", "US label only: Indian approval, strengths and warnings may differ.", "General information, not advice for any one person."]),
    c("diphenhydramine", "precaution", WARN, "If pregnant or breast-feeding, ask a health professional before use.", "If you are pregnant or breast-feeding, ask a health professional before use.", ["This is a US over-the-counter sleep-aid label. Other uses and forms of diphenhydramine are not covered.", "US label only: Indian approval, strengths and warnings may differ.", "General information, not advice for any one person."]),
    c("diphenhydramine", "monitoring", WARN, "Stop use and ask a doctor if sleeplessness persists continuously for more than 2 weeks. Insomnia may be a symptom of a serious underlying medical illness.", "Stop use and ask a doctor if sleeplessness continues for more than 2 weeks. Insomnia may be a symptom of a serious underlying medical illness.", ["This is a US over-the-counter sleep-aid label. Other uses and forms of diphenhydramine are not covered.", "US label only: Indian approval, strengths and warnings may differ.", "General information, not advice for any one person."]),
    c("diphenhydramine", "how-to-take", DOSE, "do not take more than directed adults and children 12 years and over: take 2 caplets at bedtime if needed or as directed by a doctor children under 12 years: do not use", "Do not take more than directed. Adults and children aged 12 years and over: take 2 caplets at bedtime if needed, or as directed by a doctor. Children under 12 years: do not use.", ["This is a US over-the-counter sleep-aid label. Other uses and forms of diphenhydramine are not covered.", "US label only: Indian approval, strengths and warnings may differ.", "General information, not advice for any one person."]),
    c("diphenhydramine", "urgent-help", WARN, "In case of overdose, get medical help or contact a Poison Control Center right away.", "In case of overdose, get medical help right away.", ["This is a US over-the-counter sleep-aid label. Other uses and forms of diphenhydramine are not covered.", "The label names a US Poison Control Center, which does not apply in India, so it is left out of the plain wording.", "US label only: Indian approval, strengths and warnings may differ."]),
  ];
}
